import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`ACP runtime controls for enabling dispatch, selecting backends, constraining allowed agent targets, and selecting streamed turn projection behavior.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`ACP Allowed Agents`},help:{"v1-f2mw0d-3a":`Allowlist of ACP target agent ids permitted for ACP runtime sessions. Empty means no additional allowlist restriction.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP Backend`},help:{"v1-1s1l6bz-2v":`Default ACP runtime backend id (for example: acpx). Must match a registered ACP runtime plugin backend.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`ACP Default Agent`},help:{"v1-7donnu-2c":`Fallback ACP target agent id used when ACP spawns do not specify an explicit target.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP Dispatch Enabled`},help:{"v1-1ug9t9m-3w":`Independent dispatch gate for ACP session turns (default: true). Set false to keep ACP commands available while blocking ACP turn execution.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP Enabled`},help:{"v1-1uonl1v-2a":`Global ACP feature gate. Keep disabled unless ACP runtime + policy are configured.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP Fallback Backends`},help:{"v1-1wvdifq-5m":`Ordered list of fallback ACP backend ids tried when the primary backend fails with UNAVAILABLE (for example: rate-limit / quota exhausted). Each entry must match a registered ACP runtime plugin backend.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`ACP Runtime Install Command`},help:{"v1-1jjuv9m-39":"Optional operator install/setup command shown by `/acp install` and `/acp doctor` when ACP backend wiring is missing."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP Stream`},help:{"v1-1bka5p-2v":`ACP streaming projection controls for chunk sizing, metadata visibility, and deduped delivery behavior.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`ACP Stream Delivery Mode`},help:{"v1-19gdmx1-3s":`ACP delivery style: live streams projected output incrementally, final_only buffers all projected ACP output until terminal turn events.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`ACP Stream Repeat Suppression`},help:{"v1-manh32-3d":`When true (default), suppress repeated ACP status/tool projection lines in a turn while keeping raw ACP events unchanged.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`ACP Stream Tag Visibility`},help:{"v1-1ybhx22-34":`Per-sessionUpdate visibility overrides for ACP projection (for example usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agents`},help:{"v1-2rc4v8-55":`Agent runtime configuration root. Root siblings own infrastructure and cross-agent defaults; agents.defaults owns agent-loop behavior; agent entries may override either where supported.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Agent Defaults`},help:{"v1-1af7k5b-5a":`Shared default settings inherited by agents unless overridden per entry in agents.entries. Use defaults to enforce consistent baseline behavior and reduce duplicated per-agent configuration.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Auth Inheritance Target`},help:{"v1-2d16wl-2x":`Upgrade compatibility owner for the inherited credential store until credentials are relocated per agent.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Auth Inheritance Owner`},help:{"v1-1a1s7nm-4s":`Agent whose legacy credential store remains the inheritance source after default-marker retirement. Written automatically during upgrade when the former owner was not main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Bootstrap Max Chars`},help:{"v1-drlo3i-37":`Max characters of each workspace bootstrap file injected into the system prompt before truncation (default: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Bootstrap Total Max Chars`},help:{"v1-1evwsjb-2c":`Max total characters across all injected workspace bootstrap files (default: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compaction`},help:{"v1-1qxdwz8-5p":`Compaction behavior for when context nears token limits, including strategy and pre-compaction memory flush behavior. Use this when long-running sessions need stable continuity under tight context windows.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Embedded Auto-Compaction`},help:{"v1-zmlrtm-5l":`Enable embedded proactive auto-compaction (default: true). Set false to stop threshold-driven embedded compaction while preserving Assistant overflow recovery, preflight compaction, and manual /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Compaction Identifier Policy`},help:{"v1-hby01l-4l":`Identifier-preservation policy for compaction summaries: "strict" prepends built-in opaque-identifier retention guidance (default), while "off" disables this prefix.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Compaction Keep Recent Tokens`},help:{"v1-tgysub-5h":`Minimum token budget preserved from the most recent conversation window during compaction. Use higher values to protect immediate context continuity and lower values to keep more long-tail history.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Compaction Active Transcript Size Threshold`},help:{"v1-u715n1-90":`Byte threshold that triggers normal preflight local compaction when the transcript window the model sees (since the latest compaction or reset) reaches this size (bytes or strings like "20mb"). Set to 0 or leave unset to disable. Also caps Codex app-server native rollout transcripts; oversized native threads restart fresh.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Compaction Memory Flush`},help:{"v1-18q0ve9-55":`Pre-compaction memory flush settings that run an agentic memory write before heavy compaction. Keep enabled for long sessions so salient context is persisted before aggressive trimming.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Compaction Memory Flush Enabled`},help:{"v1-9xllgp-5o":`Enables pre-compaction memory flush before the runtime performs stronger history reduction near token limits. Keep enabled unless you intentionally disable memory side effects in constrained environments.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Compaction Memory Flush Transcript Size Threshold`},help:{"v1-1rzov1e-93":`Forces pre-compaction memory flush when the model-visible transcript window reaches this threshold (bytes or strings like "2mb"). After compaction, this includes the retained tail and subsequent turns rather than discarded history. Use this to prevent long-session hangs even when token counters are stale; set to 0 to disable.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Compaction Memory Flush Model Override`},help:{"v1-1r3ctyu-7w":`Optional provider/model override used only for pre-compaction memory flush turns. Set this to a local model such as ollama/qwen3:8b when durable memory extraction should avoid the active session's paid model. The override is exact and does not inherit the active model fallback chain.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Compaction Memory Flush Soft Threshold`},help:{"v1-1dqo2l1-5c":`Threshold distance to compaction (in tokens) that triggers pre-compaction memory flush execution. Use earlier thresholds for safer persistence, or tighter thresholds for lower flush frequency.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Compaction Mid-turn Precheck`},help:{"v1-z3o2gh-6x":`Optional embedded Assistant tool-loop precheck that detects context pressure after a tool result is appended and before the next model call. When enabled, Assistant reuses existing precheck recovery to truncate tool results or compact before retrying.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Compaction Mid-turn Precheck Enabled`},help:{"v1-5t4qqe-5u":`Enable structured mid-turn context pressure checks for embedded Assistant tool loops. Default: false. Keep disabled unless long tool-heavy sessions hit context overflow before normal turn-end compaction can run.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Compaction Mode`},help:{"v1-1unahwc-76":`Compaction strategy mode: "safeguard" (the effective default when unset) applies guardrails to preserve recent context, while "default" uses baseline summarization without them. Set "default" only if safeguard summarization causes problems for your provider.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Compaction Model Override`},help:{"v1-cfeys9-6q":`Optional provider/model or configured bare alias used only for compaction summarization. Bare aliases resolve before dispatch; a configured literal model ID wins if it collides with an alias. Leave unset to keep using the primary agent model.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Compaction Notify User`},help:{"v1-lvymm8-bv":`When enabled, sends brief context-maintenance notices to the user: when compaction starts and completes (for example, '🧹 Compacting context...' and '🧹 Compaction complete'), and when a pre-compaction memory flush is exhausted so the reply continues in a degraded state (for example, '⚠️ Memory maintenance temporarily failed; continuing your reply.'). Disabled by default to keep context maintenance silent and non-intrusive.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Post-Compaction Context Sections`},help:{"v1-1n0ln2u-5f":`Opt-in AGENTS.md H2/H3 section names re-injected after compaction. Leave unset or set [] to disable reinjection. Explicitly set ["Session Startup", "Red Lines"] to enable the legacy default pair.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Compaction Post-Index Sync`},help:{"v1-ekpjeq-6l":`Controls post-compaction session memory reindex mode: "off", "async", or "await" (default: "async"). Use "await" for strongest freshness, "async" for lower compaction latency, and "off" only when session-memory sync is handled elsewhere.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Compaction Provider`},help:{"v1-kiwk91-86":`Id of a registered compaction provider plugin used for summarization. When set and the provider is registered, its summarize() method is called instead of the built-in summarizeInStages pipeline. Falls back to built-in on provider failure. Leave unset to use the default built-in summarization.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Compaction Quality Guard`},help:{"v1-u9ognp-4k":`Quality-audit retry settings for safeguard compaction summaries. Safeguard mode enables this by default; set enabled: false to skip summary audits and regeneration.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Compaction Quality Guard Enabled`},help:{"v1-1xk2vt3-36":`Enables summary quality audits and regeneration retries for safeguard compaction. Default: true in safeguard mode.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Compaction Quality Guard Max Retries`},help:{"v1-n7l46y-3y":`Maximum number of regeneration retries after a failed safeguard summary quality audit. Use small values to bound extra latency and token cost.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Compaction Preserve Recent Turns`},help:{"v1-y34ihi-5k":`Number of most recent user/assistant turns kept verbatim outside safeguard summarization (default: 3). Raise this to preserve exact recent dialogue context, or lower it to maximize compaction savings.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Compaction Thinking Level`},help:{"v1-558b7w-g1":`Thinking level used only for embedded Assistant compaction summaries: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra", or "inherit". Defaults to the provider compaction preference, otherwise "low"; native local Ollama prefers "off". Set "inherit" to reuse the session level. Explicit settings override provider defaults, and the selected level is clamped to the actual compaction model/runtime. Native Codex app-server compaction ignores this setting because its compact request has no per-operation thinking override, and Assistant logs a warning.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Compaction Timeout (Seconds)`},help:{"v1-2bhn29-7m":`Safety window in seconds for each built-in compaction model request (default: 180). Multi-stage compaction refreshes the window as each serial request starts, so the complete compaction can take longer; plugin-owned compaction receives one window for the complete operation.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Context Injection`},help:{"v1-u18x0-7u":`Controls workspace bootstrap-file injection in the embedded runtime: "always" uses normal injection (default), "continuation-skip" skips eligible continuation turns after a recorded full-bootstrap turn, and "never" disables injection. Does not control CLI-backed prompt preparation.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Default Context Limits`},help:{"v1-1coeez8-5d":`Focused per-agent-context budget defaults for selected high-volume excerpts and injected prompt blocks. Use this to tune bounded read/injection sizes without reopening any unbounded call paths.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Default memory_get Max Chars`},help:{"v1-1qb40qv-4v":`Default max characters returned by memory_get before truncation metadata and continuation notice are added. Increase to approximate older larger excerpts, but keep it bounded.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Default Post-compaction Max Chars`},help:{"v1-64qo8g-5r":`Default max characters retained from AGENTS.md during post-compaction context refresh injection. Lower this to make compaction recovery cheaper, or raise it for agents that depend on longer startup guidance.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Working Directory`},help:{"v1-1y8wlxn-6a":`Working directory for agent reply runs, separate from workspace bootstrap and memory files. Agent-specific cwd and session-spawned cwd take precedence. Supports ~ and relative paths; a distinct cwd requires an unsandboxed run.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Decision Model`},help:{"v1-7nd7ze-64":`Optional provider/model for typed choices, scores, and boolean probabilities. Unset or empty disables decision calls. Supporting plugins send bounded task evidence to this provider; chat and utility models are unchanged.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-1qo90uy-h":`Embedded Assistant`},help:{"v1-ewssxy-3k":`Embedded Assistant runner hardening controls for how workspace-local agent settings are trusted and applied in Assistant sessions.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Cyber Policy Failover`},help:{"v1-xvv6wl-2r":`Automatic Daybreak escalation for replay-safe OpenAI cyber-policy refusals in the embedded runtime.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Cyber Policy Failover Cooloff`},help:{"v1-16smtrl-25":`How long an unavailable escalation target is skipped for the current session.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Cyber Policy Failover Mode`},help:{"v1-rzsd2b-2h":`Enable automatic escalation ("auto", default) or keep provider refusals terminal ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Cyber Policy Failover Model`},help:{"v1-1aaj8nn-1t":`Provider/model target used for automatic cyber-policy escalation.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-mwwt7i-10":`Embedded Assistant Execution Contract`},help:{"v1-11yvnz8-66":`Embedded Assistant execution contract: "default" keeps the standard runner behavior, while "strict-agentic" enables structured plan tracking and non-visible turn recovery for supported OpenAI/OpenAI Codex GPT-5-family runs.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-m2d2wa-15":`Embedded Assistant Project Settings Policy`},help:{"v1-170sbck-65":'How embedded Assistant handles workspace-local `.testclaw/settings.json`: "sanitize" (default) strips shellPath/shellCommandPrefix, "ignore" disables project settings entirely, and "trusted" applies project settings as-is.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Experimental Agent Flags`},help:{"v1-cvv5cl-2w":`Experimental agent-default flags. Keep these off unless you are intentionally testing a preview surface.`}},"agents%2Edefaults%2Eexperimental%2EdecisionAssistance":{label:{"v1-1tepbyi-y":`Decision Assistance (Experimental)`},help:{"v1-uj31s4-7o":`Global opt-in for future automatic Decision experiments (default: false). Also requires an effective decisionModel for each owning agent. This foundation connects no automatic consumers and does not gate the explicit decision_evaluate tool, select providers, or grant actions.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Enable Lean Local Model Mode (Experimental)`},help:{"v1-gj06u6-7b":`Advanced troubleshooting override that restricts optional tools such as browser, automations, and message. Off by default; supported local runtimes use automatic Tool Search without this restriction. Explicit tool allows and required delivery tools are preserved.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Default Agent Fast Mode`},help:{"v1-zv4y98-2z":`Default fast-mode policy for the agent loop ("auto", true, or false). Individual agent entries override it.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Heartbeat Agent`},help:{"v1-1jynxej-3w":`Agent that owns ambient heartbeat runs when no per-agent heartbeat configuration exists. Leave unset to preserve configured-default routing.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Heartbeat Direct Policy`},help:{"v1-nhyxa9-41":`Controls whether heartbeat delivery may target direct/DM chats: "allow" (default) permits DM delivery and "block" suppresses direct-target sends.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Heartbeat Timeout (Seconds)`},help:{"v1-1se21py-5f":`Maximum time in seconds allowed for a heartbeat agent turn before it is aborted. Leave unset to use agents.defaults.timeoutSeconds when set, otherwise the heartbeat cadence capped at 600 seconds.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Human Delay Max (ms)`},help:{"v1-vnmvli-1m":`Maximum delay in ms for custom humanDelay (default: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Human Delay Min (ms)`},help:{"v1-5nrtr5-1l":`Minimum delay in ms for custom humanDelay (default: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Human Delay Mode`},help:{"v1-k7hyg3-1n":`Delay style for block replies ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Image Max Dimension (px)`},help:{"v1-vju8x-2u":`Max image side length in pixels when sanitizing transcript/tool-result image payloads (default: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Image Model Fallbacks`},help:{"v1-1kgx5i9-1b":`Ordered fallback image models (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Image Model`},help:{"v1-dstqyh-2c":`Optional image model (provider/model) used when the primary model lacks image input.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Image Quality`},help:{"v1-1uyxc5s-6u":`Image-tool media compression preference: "auto" adapts to provider/model limits and image count, "efficient" saves tokens and bytes, "balanced" keeps the current middle ground, and "high" preserves more detail for screenshots and document images.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Image Generation Model Fallbacks`},help:{"v1-oljfk4-1m":`Ordered fallback image-generation models (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Image Generation Model`},help:{"v1-g4yw0h-2o":`Optional image-generation model (provider/model) used by the shared image generation capability.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Image Generation Timeout (ms)`},help:{"v1-9yesfj-31":`Default provider request timeout in milliseconds for image_generate calls. Per-call timeoutMs overrides this.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Music Generation Model Fallbacks`},help:{"v1-wyg9xe-1m":`Ordered fallback music-generation models (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Music Generation Model`},help:{"v1-xs1e2h-2o":`Optional music-generation model (provider/model) used by the shared music generation capability.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Video Generation Model Fallbacks`},help:{"v1-wpbf1e-1m":`Ordered fallback video-generation models (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Video Generation Model`},help:{"v1-hfmlbl-2o":`Optional video-generation model (provider/model) used by the shared video generation capability.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Video Generation Timeout (ms)`},help:{"v1-1bqj80s-4i":`Default provider request timeout in milliseconds for video_generate calls. Per-call timeoutMs overrides this, and this value overrides provider-authored defaults.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Model Fallbacks`},help:{"v1-t4djq2-24":`Ordered fallback models (provider/model). Used when the primary model fails.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Primary Model`},help:{"v1-1i8a1v4-v":`Primary model (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Model Policy`},help:{"v1-z0txb7-2e":`Explicit policy for model overrides. Omit it or leave allow empty to permit any model.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Allowed Models`},help:{"v1-1fqace-3x":`Allowed model override refs. Accepts aliases, full "provider/model" refs, and provider wildcards such as "openai/*". Empty permits any model.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Models`},help:{"v1-13cvq23-4i":`Configured model catalog and per-model settings. Entries provide aliases, params, runtime metadata, and Code Mode overrides; they do not restrict model overrides.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Default Agent Model Runtime`},help:{"v1-6km9kx-41":`Optional per-model runtime policy for the default agent. Use this for model-specific runtime exceptions instead of setting a whole-agent runtime.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Default Agent Model Runtime ID`},help:{"v1-ys5y9n-4a":`Default-agent model runtime id: "testclaw", "auto", a registered plugin harness id such as "codex", or a supported CLI backend alias such as "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Code Mode`},help:{"v1-1t3e6ww-6x":`Assistant Code Mode for this exact provider/model: On forces it on, Off disables it, and Default inherits tools.codeMode.enabled. Agent-specific activation settings take precedence. This does not change the selected runtime or Codex native Code Mode.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Model Selection Scope`},help:{"v1-sj8owq-bl":`Scope for chat commands and Gateway session model updates without an explicit scope: "session" (default) changes only the current session, "agent" also updates that agent's primary, and "global" also updates the shared agents.defaults.model fallback. Explicit scope flags take precedence; configured-default writes require owner/admin authority. Telegram callback pickers and the embedded local TUI stay session-only.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`PDF Max Size (MB)`},help:{"v1-1uig1dr-1u":`Maximum PDF file size in megabytes for the PDF tool (default: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`PDF Max Pages`},help:{"v1-11na7hp-1y":`Maximum number of PDF pages to process for the PDF tool (default: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`PDF Model Fallbacks`},help:{"v1-89ebd8-19":`Ordered fallback PDF models (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF Model`},help:{"v1-2ktkxt-2y":`Optional PDF model (provider/model) for the PDF analysis tool. Defaults to imageModel, then session model.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Repo Root`},help:{"v1-j3sh74-2h":`Optional repository root shown in the system prompt runtime line (overrides auto-detect).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Sandbox Browser CDP Source Port Range`},help:{"v1-1jkowdc-2b":`Optional CIDR allowlist for container-edge CDP ingress (for example 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Sandbox Browser Network`},help:{"v1-1iu5vtl-5w":`Docker network for sandbox browser containers (default: testclaw-sandbox-browser). Use the dedicated default or a custom bridge network; "none" is unsupported because browser control requires published CDP ports.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Sandbox Docker Allow Container Namespace Join`},help:{"v1-qm39de-4c":`DANGEROUS break-glass override that allows sandbox Docker network mode container:<id>. This joins another container namespace and weakens sandbox isolation.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`Sandbox Docker GPUs`},help:{"v1-jj0yhw-4k":`Optional Docker GPU passthrough value passed to --gpus, for example "all" or "device=GPU-uuid". Requires a compatible host runtime such as NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Legacy Session Store Target`},help:{"v1-1xkej6i-2g":`Upgrade compatibility owner for retired main-agent rows and fixed legacy session stores.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Legacy Session Store Owner`},help:{"v1-ommm7e-5w":`Agent that owns retired main-agent rows or unscoped rows in a fixed legacy session store after default-marker retirement. Written automatically during upgrade when the former owner was not main or the sole agent.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Optional default skill allowlist inherited by agents that omit agents.entries.*.skills. Omit for unrestricted skills, set [] to give inheriting agents no skills, and remember explicit agents.entries.*.skills replaces this default instead of merging with it.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Skip Workspace Bootstrap Creation`},help:{"v1-kbstgw-5v":`Skips automatic creation of workspace bootstrap files, not injection of existing files. For the embedded runtime, set agents.defaults.contextInjection to "never" to disable injection unless overridden per agent.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Skipped Optional Bootstrap Files`},help:{"v1-1j2z4yj-4c":`Optional bootstrap files that should not be created in agent workspaces. Valid values: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md is accepted but a no-op).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Startup Context`},help:{"v1-1ugsihy-5o":`Runtime-owned first-turn prelude for bare "/new" and "/reset". Use this to control whether recent daily memory files are preloaded into the first prompt instead of asking the model to decide what to read.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Startup Context Apply On`},help:{"v1-wav4a5-36":`Chooses which bare reset commands get startup context: include "new", "reset", or both (default: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Startup Context Daily Memory Days`},help:{"v1-4i5xcm-3p":`Number of dated memory files to load counting backward from today in the configured user timezone (default: 2 for today + yesterday).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Enable Startup Context`},help:{"v1-1d5vz2u-4i":`Enable the startup-context prelude for bare session resets (default: true). Disable this to fall back to prompt-only behavior with no runtime-loaded daily memory.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Startup Context Max File Bytes`},help:{"v1-11cbian-41":`Maximum bytes allowed per daily memory file when building startup context (default: 16384). Files over this boundary-safe read limit are skipped.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Startup Context Max File Chars`},help:{"v1-10z53s-2u":`Maximum characters retained from each loaded daily memory file in the startup prelude (default: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Startup Context Max Total Chars`},help:{"v1-sf676u-54":`Maximum total characters retained across all loaded daily memory files in the startup prelude (default: 2800). Additional files are truncated from the prelude once this cap is reached.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Sub-agent Delegation Mode`},help:{"v1-pqewbk-5o":`Prompt-only sub-agent delegation strength. Defaults to "prefer" in each agent's main session and "suggest" elsewhere; "prefer" strongly instructs the agent to delegate non-trivial work via sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`System Agent Target`},help:{"v1-1foatwh-34":`Target settings for ambient Assistant system-agent and Custodian inference plus selected unscoped operator reads.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`System Agent Owner`},help:{"v1-15rvt92-8c":`Agent whose model and credentials own ambient system-agent and Custodian consults. Also used when models.list, models.authStatus, skills.status, doctor.memory.status, or an infer CLI command that resolves agent-owned model or auth state omits agentId or --agent; explicit request agentId always wins.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Typing Interval (Seconds)`},help:{"v1-1y701ox-42":`Controls typing-indicator keepalive cadence in seconds for every agent. Increase it to reduce update frequency across all typing-capable channels.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Typing Mode`},help:{"v1-m2hvpw-3m":`Controls when typing starts for agents: "never", "instant", "thinking", or "message". Per-agent typingMode overrides this default.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Utility Model`},help:{"v1-1wg7h1a-7s":`Optional lower-cost model (provider/model or alias) for short internal tasks such as generated titles and progress narration. Unset derives the primary provider's declared small model when available (otherwise the primary model); set to an empty string to disable utility routing.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Voice Model Fallbacks`},help:{"v1-faazv4-1b":`Ordered fallback voice models (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Voice Model`},help:{"v1-1yeh3h4-2t":`Optional voice model (provider/model) used by speech, transcription, and realtime voice capabilities.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Voice Timeout (ms)`},help:{"v1-1sbergs-32":`Default provider request timeout in milliseconds for voice model operations when the caller supports timeouts.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Workspace`},help:{"v1-1lssx8l-5w":`Default agent workspace for bootstrap and memory files. Also used as the working directory when agents.defaults.cwd is unset. Set this explicitly when running from wrappers so path resolution stays deterministic.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Agent List`},help:{"v1-yurood-5l":`Explicit list of configured agents with IDs and optional overrides for model, tools, identity, and workspace. Keep IDs stable over time so bindings, approvals, and session routing remain deterministic.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Legacy Agent Runtime`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`Legacy Agent Runtime ID`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Agent Bootstrap Max Chars`},help:{"v1-rsf1es-4j":`Per-agent override for max characters of each workspace bootstrap file injected into this agent's system prompt. Omit to inherit agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Agent Bootstrap Total Max Chars`},help:{"v1-1bal68p-4y":`Per-agent override for max total characters across all workspace bootstrap files injected into this agent's system prompt. Omit to inherit agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Agent Context Injection`},help:{"v1-1j68ys8-50":`Per-agent override for workspace bootstrap-file injection in the embedded runtime. Omit to inherit agents.defaults.contextInjection. Does not control CLI-backed prompt preparation.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Agent Context Limits`},help:{"v1-f1qxq8-3c":`Optional per-agent overrides for the focused context budget knobs. Omitted fields inherit agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Agent memory_get Max Chars`},help:{"v1-12hlmsv-1v":`Per-agent override for the default memory_get max character budget.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Agent Post-compaction Max Chars`},help:{"v1-15s0npd-1w":`Per-agent override for the post-compaction AGENTS.md excerpt budget.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Agent Working Directory`},help:{"v1-mv43ak-6a":`Working directory for this agent's reply runs. Overrides agents.defaults.cwd but not session-spawned cwd; bootstrap and memory files stay in workspace. Supports ~ and relative paths; a distinct cwd requires an unsandboxed run.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Agent Decision Model`},help:{"v1-1mih8bf-3j":`Per-agent decision model. Unset inherits agents.defaults.decisionModel; an empty string disables decision calls for this agent.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-1y1lf37-n":`Agent Embedded Assistant`},help:{"v1-s18aq2-4b":`Optional per-agent embedded Assistant overrides. Use this to opt specific agents into stricter GPT-5 execution behavior without changing the global default.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-dqcvnx-16":`Agent Embedded Assistant Execution Contract`},help:{"v1-zfvlfy-7k":`Optional per-agent embedded Assistant execution contract override. Set "strict-agentic" to enable structured plan tracking and non-visible turn recovery for that agent on supported OpenAI/OpenAI Codex GPT-5-family runs, or "default" to inherit the standard runner behavior.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Agent Experimental Flags`},help:{"v1-1r06jov-2a":`Per-agent experimental flags. Omitted fields inherit agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Agent Lean Local Model Mode`},help:{"v1-5o3tgx-58":`Per-agent troubleshooting override for lean local-model mode. Enable it only when restricting optional tools resolves a demonstrated model failure, without trimming tools from every agent.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Agent Fast Mode Default`},help:{"v1-1ujydjc-3o":`Optional per-agent default for fast mode ("auto", true, or false). Applies when no per-message or session fast-mode override is set.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Heartbeat Direct Policy`},help:{"v1-11gl9l0-41":`Per-agent override for heartbeat direct/DM delivery policy; use "block" for agents that should only send heartbeat alerts to non-DM destinations.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Heartbeat Timeout (Seconds)`},help:{"v1-kdetv4-6s":`Per-agent maximum time in seconds allowed for a heartbeat agent turn before it is aborted. Leave unset to inherit the merged heartbeat timeout, then agents.defaults.timeoutSeconds when set, otherwise the heartbeat cadence capped at 600 seconds.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Identity Avatar`},help:{"v1-pzp9gr-1t":`Agent avatar (workspace-relative path, http(s) URL, or data URI).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Agent Model Policy`},help:{"v1-17d5je8-2r":`Per-agent model override policy. An explicit allow list replaces the default policy for this agent.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Allowed Agent Models`},help:{"v1-v1ueke-5b":`Allowed model override refs for this agent. Accepts aliases, full "provider/model" refs, and trailing prefix wildcards such as "provider/*" or "provider/namespace/*"; empty permits any model.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Agent Model Overrides`},help:{"v1-nld1vq-1v":`Per-agent model catalog overrides keyed by full provider/model IDs.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Agent Model Runtime`},help:{"v1-7b59y-3s":`Optional per-model runtime policy for this agent. Use this for agent-specific model exceptions instead of setting a whole-agent runtime.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Agent Model Runtime ID`},help:{"v1-1jqsi5-46":`Per-agent model runtime id: "testclaw", "auto", a registered plugin harness id such as "codex", or a supported CLI backend alias such as "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Code Mode`},help:{"v1-bs4imv-7m":`Assistant Code Mode for this agent and exact provider/model: On forces it on, Off disables it, and Default inherits the agent activation setting, then the shared model override, then tools.codeMode.enabled. This does not change the selected runtime or Codex native Code Mode.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Agent Reasoning Default`},help:{"v1-13ly0xf-3m":`Optional per-agent default reasoning visibility (on|off|stream). Applies when no per-message or session reasoning override is set.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Agent Runtime`},help:{"v1-1qgy6dj-3l":`Optional runtime descriptor for this agent. Use embedded for default Assistant execution or acp for external ACP harness defaults.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Agent ACP Runtime`},help:{"v1-91zvdk-3i":`ACP runtime defaults for this agent when runtime.type=acp. Binding-level ACP overrides still take precedence per conversation.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agent ACP Harness Agent`},help:{"v1-q4rtk1-37":`Optional ACP harness agent id to use for this Assistant agent (for example codex, claude, cursor, gemini, testclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Agent ACP Backend`},help:{"v1-1u3cdsg-2n":`Optional ACP backend override for this agent's ACP sessions (falls back to global acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Agent ACP Working Directory`},help:{"v1-d9p9rf-1t":`Optional default working directory for this agent's ACP sessions.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Agent ACP Mode`},help:{"v1-yatuk4-21":`Optional ACP session mode default for this agent (persistent or oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Agent Runtime Type`},help:{"v1-1x2gnei-2r":`Runtime type for this agent: "embedded" (default Runtime) or "acp" (ACP harness defaults).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Agent Sandbox Browser CDP Source Range`},help:{"v1-1q1qyso-1d":`Per-agent override for CDP source CIDR allowlist.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Agent Sandbox Browser Network`},help:{"v1-13bdfww-4c":`Per-agent override for the sandbox browser Docker network. Use a bridge network; "none" is unsupported because browser control requires published CDP ports.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Agent Sandbox Docker Allow Container Namespace Join`},help:{"v1-1xtnseb-2i":`Per-agent DANGEROUS override for container namespace joins in sandbox Docker network mode.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Agent Sandbox Docker GPUs`},help:{"v1-1kek1n2-1t":`Per-agent Docker GPU passthrough override for sandbox containers.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Agent Skill Filter`},help:{"v1-igchue-6v":`Optional allowlist of skills for this agent. If omitted, the agent inherits agents.defaults.skills when set; otherwise skills stay unrestricted. Set [] for no skills. An explicit list fully replaces inherited defaults instead of merging with them.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Agent Skills Limits`},help:{"v1-1sv10v9-4y":`Optional per-agent overrides for skills subsystem budgets. Use this when an agent needs a different skills prompt budget without introducing a second generic context-limits path.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Agent Skills Prompt Max Chars`},help:{"v1-dys63y-52":`Per-agent override for the skills prompt character budget. This extends the existing skills.limits.maxSkillsPromptChars path instead of routing the same budget through contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Sub-agent Delegation Mode`},help:{"v1-1rkgh6p-4s":`Per-agent override for sub-agent delegation strength. Omit to use "prefer" in this agent's main session and "suggest" elsewhere; explicit "prefer" or "suggest" always wins.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Agent Thinking Default`},help:{"v1-173q7vy-43":`Optional per-agent default thinking level. Overrides agents.defaults.thinkingDefault for this agent when no per-message or session override is set.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Agent Tool Allowlist Additions`},help:{"v1-1550ui9-46":`Per-agent additive allowlist for tools on top of global and profile policy. Keep narrow to avoid accidental privilege expansion on specialized agents.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Agent Tool Policy by Provider`},help:{"v1-mthxv9-4t":`Per-agent provider-specific tool policy overrides for channel-scoped capability control. Use this when a single agent needs tighter restrictions on one provider than others.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Agent Code Mode`},help:{"v1-118t8u5-65":`Per-agent Code Mode options. Explicit enabled overrides the shared model and global activation defaults; an agent-specific model codeMode override wins. Other options merge over tools.codeMode without changing activation.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Agent Exec Timeout (Seconds)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Agent GitHub CLI Identity Override`},help:{"v1-mjwdh4-38":`Complete managed GitHub CLI identity and Git author override for this agent. Omit it to inherit the system identity.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Agent Git Author Email`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Agent Git Author Name`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Agent GitHub Credential Kind`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Agent GitHub Profile Version`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Agent Message Action Allowlist`},help:{"v1-1g5gov3-67":`Per-agent message action allowlist for the message tool. Set to a minimal list such as ["send"] for public sandbox agents so read, edit, delete, reaction, and other provider-specific message actions stay hidden and blocked.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Agent Cross-Context Messaging (Across Providers)`},help:{"v1-pehesn-49":`Per-agent override for sending across providers. Inherits the global setting (default: true). Set false to block cross-provider messaging for this agent.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Agent Cross-Context Messaging (Same Provider)`},help:{"v1-s9u09h-4t":`Per-agent message guard for sending to other conversations on the same provider. Set both this and allowAcrossProviders to false for current-conversation-only public agents.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Agent Tool Profile`},help:{"v1-1du76ix-57":`Per-agent override for tool profile selection when one agent needs a different capability baseline. Use this sparingly so policy differences across agents stay intentional and reviewable.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Agent Swarm`},help:{"v1-420ljs-2c":`Per-agent swarm override. Values merge over the top-level tools.swarm configuration.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Agent Typing Mode`},help:{"v1-oxir52-2e":`Overrides the default typing start policy for one agent without changing other agents.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Agent Utility Model`},help:{"v1-1v9oskz-2z":`Optional per-agent utility model override for short internal tasks. Overrides agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Agent Ownership Generation`},help:{"v1-1m4ebc5-8g":`Durable multi-agent ownership generation marker. "explicit" means ambient channels, heartbeat, system-agent consults, Talk, cron, and bare CLI operations must resolve a surface-specific owner or fail closed. Assistant stamps this automatically when creating or migrating a fleet; omit it for a sole agent.`}},approvals:{label:{"v1-1m405m7-9":`Approvals`},help:{"v1-4y3in-5w":`Approval routing controls for forwarding exec and plugin approval requests to chat destinations outside the originating session. Keep these disabled unless operators need explicit out-of-band approval visibility.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Exec Approval Forwarding`},help:{"v1-1r2mozk-5v":`Groups exec-approval forwarding behavior including enablement, routing mode, filters, and explicit targets. Configure here when approval prompts must reach operational channels instead of only the origin thread.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Approval Agent Filter`},help:{"v1-xbuhd3-5i":'Optional allowlist of agent IDs eligible for forwarded approvals, for example `["primary", "ops-agent"]`. Use this to limit forwarding blast radius and avoid notifying channels for unrelated agents.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Forward Exec Approvals`},help:{"v1-1t0whe8-5s":`Enables forwarding of exec approval requests to configured delivery destinations (default: false). Keep disabled in low-risk setups and enable only when human approval responders need channel-visible prompts.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Approval Forwarding Mode`},help:{"v1-1dedfo4-69":`Controls where approval prompts are sent: "session" uses origin chat, "targets" uses configured targets, and "both" sends to both paths. Use "session" as baseline and expand only when operational workflow requires redundancy.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Approval Session Filter`},help:{"v1-smeg8e-5u":'Optional session-key filters matched as substring or regex-style patterns, for example `["discord:", "^agent:ops:"]`. Use narrow patterns so only intended approval contexts are forwarded to shared destinations.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Approval Forwarding Targets`},help:{"v1-17ah848-5u":`Explicit delivery targets used when forwarding mode includes targets, each with channel and destination details. Keep target lists least-privilege and validate each destination before enabling broad forwarding.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Approval Target Account ID`},help:{"v1-16zopng-5e":`Optional account selector for multi-account channel setups when approvals must route through a specific account context. Use this only when the target channel has multiple configured identities.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Approval Target Channel`},help:{"v1-ji1igl-59":`Channel/provider ID used for forwarded approval delivery, such as discord, slack, or a plugin channel id. Use valid channel IDs only so approvals do not silently fail due to unknown routes.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Approval Target Thread ID`},help:{"v1-1axynw7-59":`Optional thread/topic target for channels that support threaded delivery of forwarded approvals. Use this to keep approval traffic contained in operational threads instead of main channels.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Approval Target Destination`},help:{"v1-1ijng7e-5n":`Destination identifier inside the target channel (channel ID, user ID, or thread root depending on provider). Verify semantics per provider because destination format differs across channel integrations.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Plugin Approval Forwarding`},help:{"v1-1m6pzxv-6b":`Groups plugin-approval forwarding behavior including enablement, routing mode, filters, and explicit targets. Independent of exec approval forwarding. Configure here when plugin approval prompts must reach operational channels.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Plugin Approval Agent Filter`},help:{"v1-jb1bra-4b":'Optional allowlist of agent IDs eligible for forwarded plugin approvals, for example `["primary", "ops-agent"]`. Use this to limit forwarding blast radius.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Forward Plugin Approvals`},help:{"v1-1ntctaf-3v":`Enables forwarding of plugin approval requests to configured delivery destinations (default: false). Independent of approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Plugin Approval Forwarding Mode`},help:{"v1-1h62vy4-3z":`Controls where plugin approval prompts are sent: "session" uses origin chat, "targets" uses configured targets, and "both" sends to both paths.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Plugin Approval Session Filter`},help:{"v1-1eppxmt-57":'Optional session-key filters matched as substring or regex-style patterns, for example `["discord:", "^agent:ops:"]`. Use narrow patterns so only intended approval contexts are forwarded.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Plugin Approval Forwarding Targets`},help:{"v1-o92qze-3k":`Explicit delivery targets used when plugin approval forwarding mode includes targets, each with channel and destination details.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Plugin Approval Target Account ID`},help:{"v1-1wf3lqn-3j":`Optional account selector for multi-account channel setups when plugin approvals must route through a specific account context.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Plugin Approval Target Channel`},help:{"v1-1mzhzi9-34":`Channel/provider ID used for forwarded plugin approval delivery, such as discord, slack, or a plugin channel id.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Plugin Approval Target Thread ID`},help:{"v1-1scaw9c-2v":`Optional thread/topic target for channels that support threaded delivery of forwarded plugin approvals.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Plugin Approval Target Destination`},help:{"v1-sh5te1-31":`Destination identifier inside the target channel (channel ID, user ID, or thread root depending on provider).`}},attachments:{label:{"v1-8925gh-b":`Attachments`},help:{"v1-1xvgkss-40":`Top-level retention behavior shared across providers and tools that persist media. Use ttlHours when general staged media needs bounded cleanup.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Attachment Retention TTL (hours)`},help:{"v1-1g90day-9e":`Optional retention window in hours for persisted media handled by the general mtime sweep. Leave unset to disable that sweep, or set values like 24 (1 day) or 168 (7 days) to periodically remove older staged media. Managed outgoing media (chat-generated attachments) is excluded and follows its own SQLite- and transcript-aware retention.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Auth`},help:{"v1-1eu3aud-5c":`Authentication profile root used for multi-profile provider credentials and cooldown-based failover ordering. Keep profiles minimal and explicit so automatic failover behavior stays auditable.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Auth Profile Order`},help:{"v1-1x6kknp-1w":`Ordered auth profile IDs per provider (used for automatic failover).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Auth Profiles`},help:{"v1-kzoqcn-1j":`Named auth profiles (provider + mode + optional email).`}},bindings:{label:{"v1-1hcih9f-8":`Bindings`},help:{"v1-y7hrzb-4i":`Top-level binding rules for routing and persistent ACP conversation ownership. Use type=route for normal routing and type=acp for persistent ACP harness bindings.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`ACP Binding Overrides`},help:{"v1-1t4lisi-44":`Optional per-binding ACP overrides for bindings[].type=acp. This layer overrides agents.entries.*.runtime.acp defaults for the matched conversation.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`ACP Binding Backend`},help:{"v1-rsrbkp-2x":`ACP backend override for this binding (falls back to agent runtime ACP backend, then global acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`ACP Binding Working Directory`},help:{"v1-ngpkj0-1y":`Working directory override for ACP sessions created from this binding.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`ACP Binding Label`},help:{"v1-azce82-23":`Human-friendly label for ACP status/diagnostics in this bound conversation.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`ACP Binding Mode`},help:{"v1-cgq8xv-1v":`ACP session mode override for this binding (persistent or oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Binding Agent ID`},help:{"v1-17ra0cl-4m":`Target agent ID that receives traffic when the corresponding binding match rule is satisfied. Use valid configured agent IDs only so routing does not fail at runtime.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Binding Match Rule`},help:{"v1-sc1w2e-51":`Match rule object for deciding when a binding applies, including channel and optional account/peer constraints. Keep rules narrow to avoid accidental agent takeover across contexts.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Binding Account ID`},help:{"v1-1d209g7-56":`Optional account selector for multi-account channel setups so the binding applies only to one identity. Use this when account scoping is required for the route and leave unset otherwise.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Binding Channel`},help:{"v1-d22m5-54":"Channel/provider identifier this binding applies to, such as `telegram`, `discord`, or a plugin channel ID. Use the configured channel key exactly so binding evaluation works reliably."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Binding Guild ID`},help:{"v1-jzzfj1-4x":`Optional Discord-style guild/server ID constraint for binding evaluation in multi-server deployments. Use this when the same peer identifiers can appear across different guilds.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Binding Peer Match`},help:{"v1-gcjxff-4i":`Optional peer matcher for specific conversations including peer kind and peer id. Use this when only one direct/group/channel target should be pinned to an agent.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Binding Peer ID`},help:{"v1-86fbh7-4b":`Conversation identifier used with peer matching, such as a chat ID, channel ID, or group ID from the provider. Keep this exact to avoid silent non-matches.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Binding Peer Kind`},help:{"v1-uufscp-4x":`Peer conversation type: "direct", "group", "channel", or legacy "dm" (deprecated alias for direct). Prefer "direct" for new configs and keep kind aligned with channel semantics.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Binding Roles`},help:{"v1-6s891m-4k":`Optional role-based filter list used by providers that attach roles to chat context. Use this to route privileged or operational role traffic to specialized agents.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Binding Team ID`},help:{"v1-hh9ps2-48":`Optional team/workspace ID constraint used by providers that scope chats under teams. Add this when you need bindings isolated to one workspace context.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Binding Session`},help:{"v1-x325l2-4v":`Optional route session overrides for conversations matched by this binding. Use this when a narrow route should keep the same agent but isolate session continuity differently.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Binding Session DM Scope`},help:{"v1-10sg3xw-4s":`Optional DM session scope override for this route binding. For example, keep global session.dmScope="main" while using "per-account-channel-peer" for selected direct peers.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Binding Session Group Scope`},help:{"v1-1ys2u7k-6n":`Optional group/channel session scope override for this route binding. "per-group" keeps matched rooms separate and ambiently watched by the agent main session regardless of dmScope; "main" merges their context into main and needs no watch.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Binding Type`},help:{"v1-172mhtk-3o":`Binding kind. Use "route" (or omit for legacy route entries) for normal routing, and "acp" for persistent ACP conversation bindings.`}},broadcast:{label:{"v1-awqjh0-j":`Agent Group Threads`},help:{"v1-1tz72sr-6b":`Use agent group threads to run several configured agents on one inbound conversation, each in its own session. Channel-qualified entries support bounded follow-up rounds; legacy WhatsApp peer arrays retain single-pass behavior.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Agent Group Participants and Options`},help:{"v1-1b63zmt-7d":`Use a channel-qualified peer ID (for example "telegram:-100123") to configure an array of agent IDs or a strict object with agents, mentionGating, maxRounds, and maxTurns. Qualified entries take precedence over legacy WhatsApp peer keys and allow at most 16 agents.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Agent Group Participants`},help:{"v1-g5o0ky-43":`Participant agent IDs from agents.entries (maximum: 16). Each participant uses its own session for this channel, account, conversation, and thread.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Agent Group Maximum Rounds`},help:{"v1-i6v4jc-5a":`Maximum rounds per inbound message, including the initial round (integer: 1–4, default: 1). Follow-up rounds share bounded, attributed sibling replies and stop when every participant passes.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Agent Group Maximum Turns`},help:{"v1-1kiv8dy-72":`Maximum participant turns per inbound message across all rounds (integer: 1–32, default: agents.length). Slots are reserved before parallel dispatch; this bounds agent turns, not physical message chunks or tool sends. Budgets do not resume after restart.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Agent Group Mention Selection`},help:{"v1-uay9zu-5u":`Select only explicitly @mentioned participants when any match; otherwise run all participants (default: true). Bare names or emoji do not select participants. Channel allowlists and admission rules still apply.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Agent Group Strategy`},help:{"v1-p4k9hu-4q":`Participant execution order: "parallel" (default) runs agents concurrently, while "sequential" runs them in configured order. Each round completes before the next begins.`}},browser:{label:{"v1-13dzmen-7":`Browser`},help:{"v1-5b74wi-5l":`Browser runtime controls for local or remote CDP attachment, profile routing, and screenshot/snapshot behavior. Keep defaults unless your automation workflow requires custom browser transport settings.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Allow System Profile Import`},help:{"v1-3x09ng-5w":`Allows macOS hosts to import cookies from a local Chrome-family system profile into a managed Assistant browser profile. Disable this to prevent browser profile cookie import and its macOS Keychain consent prompt.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Browser Attach-only Mode`},help:{"v1-xaw7xm-4s":`Restricts browser mode to attach-only behavior without starting local browser processes. Use this when all browser sessions are externally managed by a remote CDP provider.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`Browser CDP URL`},help:{"v1-2n72jb-65":`CDP/DevTools endpoint URL used to attach to an externally managed browser instance. Use this for centralized browser hosts, tunnels, or existing-session attachment, and keep URL access restricted to trusted network paths.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Browser Default Profile`},help:{"v1-a6xo96-52":`Default browser profile name selected when callers do not explicitly choose a profile. Use a stable low-privilege profile as the default to reduce accidental cross-context state use.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Browser Enabled`},help:{"v1-19qr4oj-56":`Enables browser capability wiring in the gateway so browser tools and CDP-driven workflows can run. Disable when browser automation is not needed to reduce surface area and startup work.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Browser Evaluate Enabled`},help:{"v1-1oa79mq-59":`Enables browser-side evaluate helpers for runtime script evaluation capabilities where supported. Keep disabled unless your workflows require evaluate semantics beyond snapshots/navigation.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Browser Executable Path`},help:{"v1-1plb4ki-6i":`Explicit browser executable path when auto-discovery is insufficient for your host environment. Use an absolute stable path, or a path starting with ~ for your OS home directory, so launch behavior stays deterministic across restarts.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Browser Extension Relay`},help:{"v1-6ywlwr-4e":`Chrome extension relay authentication compatibility settings. Keep the legacy window only while older paired extensions or external CDP clients still need it.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Allow Legacy Browser Relay Auth`},help:{"v1-pj2e90-63":`Temporarily accepts legacy Bearer, Basic, and token-subprotocol relay authentication. Default: true for one migration window. Set false after every extension and external CDP client uses Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Browser Headless Mode`},help:{"v1-1rswq8j-5a":`Forces browser launch in headless mode when the local launcher starts browser instances. Keep headless enabled for server environments and disable only when visible UI debugging is required.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Browser No-Sandbox Mode`},help:{"v1-slntux-4w":`Disables Chromium sandbox isolation flags for environments where sandboxing fails at runtime. Keep this off whenever possible because process isolation protections are reduced.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Browser Profiles`},help:{"v1-1x8lf05-51":`Named browser profile connection map used for explicit routing to CDP ports or URLs with optional metadata. Keep profile names consistent and avoid overlapping endpoint definitions.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Browser Profile Attach-only Mode`},help:{"v1-2b5zs0-5a":`Per-profile attach-only override that skips local browser launch and only attaches to an existing CDP endpoint. Useful when one profile is externally managed but others are locally launched.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Browser Profile CDP Port`},help:{"v1-gx1yiq-49":`Per-profile local CDP port used when connecting to browser instances by port instead of URL. Use unique ports per profile to avoid connection collisions.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`Browser Profile CDP URL`},help:{"v1-x491r0-64":`Per-profile CDP/DevTools endpoint URL used for explicit browser routing by profile name. Use this for remote CDP hosts, tunnels, or existing-session profiles that should attach through a running Chrome DevTools endpoint.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Browser Profile Driver`},help:{"v1-1pozva-5r":`Per-profile browser driver mode. Use "testclaw" (or legacy "clawd") for CDP-based profiles, "existing-session" for Chrome DevTools MCP attachment, or "extension" for the authenticated Chrome extension relay.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Browser Profile Executable Path`},help:{"v1-29azyv-4w":`Per-profile browser executable path for locally launched managed browser profiles. Overrides browser.executablePath and accepts paths starting with ~ for the OS home directory.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Browser Profile Headless Mode`},help:{"v1-p4jtgv-4u":`Per-profile headless override for locally launched browser instances. Use this when one profile should stay headless without forcing browser.headless for every other profile.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Browser Profile Chrome MCP Args`},help:{"v1-rc45ke-5g":`Extra per-profile Chrome DevTools MCP arguments for existing-session attachment, such as --no-usage-statistics. Endpoint arguments here override the built-in auto-connect or browser URL selection.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Browser Profile Chrome MCP Command`},help:{"v1-1xpty8o-2h":`Per-profile Chrome DevTools MCP command for existing-session attachment. Defaults to npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Browser Profile User Data Dir`},help:{"v1-5xvgex-9h":`Per-profile Chromium user data directory for existing-session attachment through Chrome DevTools MCP. Use this for Brave, Edge, Chromium, or non-default Chrome profiles when the built-in auto-connect path would pick the wrong browser data directory on the selected host or browser node. Paths starting with ~ expand to the OS home directory.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Browser Snapshot Defaults`},help:{"v1-v19wdy-4y":`Default snapshot capture configuration used when callers do not provide explicit snapshot options. Tune this for consistent capture behavior across channels and automation paths.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Browser Snapshot Mode`},help:{"v1-joeyxp-5c":`Default snapshot extraction mode controlling how page content is transformed for agent consumption. Choose the mode that balances readability, fidelity, and token footprint for your workflows.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Browser SSRF Policy`},help:{"v1-1qbp9im-5e":`Server-side request forgery guardrail settings for browser/network fetch paths that could reach internal hosts. Keep restrictive defaults in production and open only explicitly approved targets.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Browser Allowed Hostnames`},help:{"v1-1rng39-2k":`Exact hostnames or IP literals allowed by browser SSRF policy checks. Keep the list minimal.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Browser Allow IPv6 Unique Local Range`},help:{"v1-1glx5cy-2c":`Allow IPv6 Unique Local Addresses (fc00::/7) for trusted fake-IP proxy environments.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Browser Allow RFC 2544 Benchmark Range`},help:{"v1-10ateu3-2i":`Allow RFC 2544 benchmark-range IPs (198.18.0.0/15) for trusted fake-IP proxy environments.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Browser Blocked Hostnames`},help:{"v1-nug0we-6k":`Hostname patterns denied before DNS and allow rules, even with private-network access enabled. Supports exact hosts and "*.example.com" for subdomains only; add "example.com" separately to block the apex. Empty or unset adds no denials.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Browser Dangerously Allow Private Network`},help:{"v1-17103pi-4m":`Allows access to private-network address ranges from browser tooling. Default is disabled when unset; enable only for explicitly trusted private-network destinations.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Browser Tab Cleanup`},help:{"v1-1ctwaad-4y":`Best-effort cleanup policy for browser tabs opened by primary-agent sessions. Keep enabled to avoid stale sandbox or managed-browser tabs accumulating across long-lived gateways.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Browser Tab Cleanup Enabled`},help:{"v1-4sv97p-3u":`Enables cleanup of idle tracked browser tabs for primary-agent sessions. Disable only when external tooling owns tab lifecycle completely.`}},channels:{label:{"v1-1ju93md-8":`Channels`},help:{"v1-12yv6ma-5n":`Channel provider configurations plus shared defaults that control access policies, heartbeat visibility, and per-surface behavior. Keep defaults centralized and override per provider only where required.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Channel Defaults`},help:{"v1-uz6veb-4p":`Default channel behavior applied across providers when provider-specific settings are not set. Use this to enforce consistent baseline policy before per-provider tuning.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Default Bot Loop Protection`},help:{"v1-1lpznyk-4w":`Default pair loop protection settings for channel providers that support bot-to-bot loop guards. Use provider-specific overrides only when one channel needs a different budget.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Default Bot Loop Cooldown Seconds`},help:{"v1-1yl5ird-2z":`Cooldown seconds applied to a pair after it exceeds the loop budget. Default for supporting channels is 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Default Bot Loop Protection Enabled`},help:{"v1-3ruik-4r":`Enables pair loop protection by default for supporting channels when bot-authored messages can reach dispatch. Providers may still disable the guard when bots are ignored.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Default Bot Loop Events per Window`},help:{"v1-1u0mdjc-41":`Maximum events a sender/receiver pair may exchange within the configured window before suppression starts. Default for supporting channels is 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Default Bot Loop Window Seconds`},help:{"v1-12xpmen-2m":`Sliding window length in seconds for pair loop budgets. Default for supporting channels is 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Default Context Visibility`},help:{"v1-1hze3g1-5o":`Default supplemental context visibility for fetched quote/thread/history content: "all" (keep all context), "allowlist" (only allowlisted senders), or "allowlist_quote" (allowlist + keep explicit quotes).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Default Group Policy`},help:{"v1-ntl9m4-4n":`Default group policy across channels: "open", "disabled", or "allowlist". Keep "allowlist" for safer production setups unless broad group participation is intentional.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Default Heartbeat Visibility`},help:{"v1-49bw75-4v":`Default heartbeat visibility settings for status messages emitted by providers/channels. Tune this globally to reduce noisy healthy-state updates while keeping alerts visible.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Heartbeat Show Alerts`},help:{"v1-8dk8zx-4g":`Shows degraded/error heartbeat alerts when true so operator channels surface problems promptly. Keep enabled in production so broken channel states are visible.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Heartbeat Show OK`},help:{"v1-17tg3mk-4z":`Shows healthy/OK heartbeat status entries when true in channel status outputs. Keep false in noisy environments and enable only when operators need explicit healthy confirmations.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Heartbeat Use Indicator`},help:{"v1-1w12cs2-4m":`Enables concise indicator-style heartbeat rendering instead of verbose status text where supported. Use indicator mode for dense dashboards with many active channels.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Default Implicit Mentions`},help:{"v1-4gtdyv-48":`Default policy for whether reply-to-bot, quoted-bot, and bot-participated-thread facts activate supporting message channels without an explicit mention.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Default Quoted-Bot Implicit Mentions`},help:{"v1-va1u5v-2v":`Treat quoted bot messages as implicit mentions by default. Defaults to true for backward compatibility.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Default Reply-to-Bot Implicit Mentions`},help:{"v1-lm44c3-39":`Treat replies to the bot's own messages as implicit mentions by default. Defaults to true for backward compatibility.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Default Thread-Participation Implicit Mentions`},help:{"v1-160205h-3o":`Treat follow-ups in threads where the bot participated as implicit mentions by default. Defaults to true for backward compatibility.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Channel Model Overrides`},help:{"v1-1b01spx-2p":`Map provider -> channel id / DM peer id -> model override (values are provider/model or aliases).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Cloud Workers`},help:{"v1-10carc4-5v":`Opt-in cloud worker profiles for disposable remote environments. When this section is omitted or has no profiles, cloud worker creation remains unavailable and existing gateway/node status behavior is unchanged.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Cloud Worker Desktop (Labs)`},help:{"v1-vllayc-3n":`Enables the experimental worker.desktop.observe surface and Control UI Desktop panel for desktop-capable cloud worker environments.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Cloud Worker Prepared Pool`},help:{"v1-rw51o5-6b":`Limits for prepared cloud workers kept ready for later sessions. Reserves incur running-machine charges until provider cleanup completes; their fixed expiry follows actual project demand and the provider's existing idle policy.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Cloud Worker Ready Reserve Cap`},help:{"v1-1mpd1dt-7u":`Gateway-wide cap on unassigned prepared cloud workers across projects and profiles (default: 4). Preparing workers and unconfirmed reserve cleanup count toward the cap. Set 0 to drain unassigned reserves and disable replenishment while preserving snapshot reuse and active sessions.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Cloud Worker Profiles`},help:{"v1-eii67l-3j":`Named cloud worker profiles. Each profile selects a worker provider registered by a plugin and carries provider-owned settings.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Cloud Worker Profile`},help:{"v1-1v2w7jl-4u":`One cloud worker profile selected by name when creating an environment. Keep provider credentials in supported references rather than embedding secret material in this block.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Cloud Worker Install Method`},help:{"v1-blrtbf-74":`Worker installation method: "bundle" (default) transfers the gateway's content-hashed installed build and supports released, development, and unreleased versions; "npm" installs the exact gateway version and is available only when that version is released.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Cloud Worker Provider`},help:{"v1-1p4s4c1-44":`Worker provider id registered by a plugin. The configured plugin must expose this id before the gateway can provision environments from the profile.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Cloud Worker Ready Reserve Target`},help:{"v1-1nwve9s-7w":`Target unassigned prepared workers per eligible project using this profile (default: 1), subject to the Gateway-wide prepared pool cap. Set 0 to disable this profile's reserves while preserving snapshot reuse. Preparing workers and unconfirmed reserve cleanup count toward the target.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Cloud Worker Provider Settings`},help:{"v1-mq7u32-4j":`Provider-owned settings validated by the selected plugin. Use SecretRef objects for secret-bearing values; opaque settings do not gain automatic secret resolution.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Cloud Worker Idle Suspend Duration`},help:{"v1-1keuwgh-4w":`Automatically reclaims an idle cloud worker after this duration, such as 45m or 2h; the next message provisions a replacement. Minimum: 1m. Leave unset to keep workers running.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Cloud Worker Project Profiles`},help:{"v1-1kkfrif-46":`Default cloud worker profile names keyed by normalized lowercase repository identity (host/owner/repo). Explicit dispatch profile ids take precedence.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Cloud Worker Project Profile`},help:{"v1-1mux5u0-30":`Cloud worker profile name used by default when a session worktree's origin matches this repository identity.`}},commands:{label:{"v1-15x4mpf-8":`Commands`},help:{"v1-1gi0dr2-5a":`Controls chat command surfaces, owner gating, and elevated command access behavior across providers. Keep defaults unless you need stricter operator controls or broader command availability.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Command Elevated Access Rules`},help:{"v1-7azkw-5g":`Defines elevated command allow rules by channel and sender for owner-level command surfaces. Use narrow provider-specific identities so privileged commands are not exposed to broad chat audiences.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Allow Bash Chat Command`},help:{"v1-83ah7w-36":"Allow bash chat command (`!`; `/bash` alias) to run host shell commands (default: false; requires tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bash Foreground Window (ms)`},help:{"v1-1o0o4dw-2c":`How long bash waits before backgrounding (default: 2000; 0 backgrounds immediately).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Allow /config`},help:{"v1-151bb7c-21":`Allow /config chat command to read/write config on disk (default: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Allow /debug`},help:{"v1-y1lc3j-1y":`Allow /debug chat command for runtime-only overrides (default: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Allow /mcp`},help:{"v1-130h0pd-2o":`Allow /mcp chat command to manage Assistant MCP server config under mcp.servers (default: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Native Commands`},help:{"v1-dighr2-5n":`Registers native slash/menu commands with channels that support command registration (Discord, Slack, Telegram). Keep enabled for discoverability unless you intentionally run text-only command workflows.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Native Skill Commands`},help:{"v1-19gtqci-5h":`Registers native skill commands so users can invoke skills directly from provider command menus where supported. Keep aligned with your skill policy so exposed commands match what operators expect.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Command Owners`},help:{"v1-1di38gv-3y":`Explicit owner allowlist for owner-scoped commands. Use channel-native IDs (optionally prefixed like "whatsapp:+15551234567"). '*' is ignored.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Allow /plugins`},help:{"v1-akwy9y-33":`Allow /plugins chat command to list discovered plugins and toggle plugin enablement in config (default: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Allow Restart`},help:{"v1-m32fv2-27":`Allow /restart, /update, and external SIGUSR2 restart requests (default: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Text Commands`},help:{"v1-1utu76s-5j":`Enables text-command parsing in chat input in addition to native command surfaces where available. Keep this enabled for compatibility across channels that do not support native command registration.`}},cron:{label:{"v1-1qlte4b-b":`Automations`},help:{"v1-4md8ic-5u":`Global scheduler settings for stored automations, run concurrency, delivery fallback, and run-session retention. Keep defaults unless you are scaling automation volume or integrating external webhook receivers.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automations Enabled`},help:{"v1-y8otx6-5i":`Enables automation execution for stored schedules managed by the gateway. Keep enabled for normal reminder/automation flows, and disable only to pause all automation execution without deleting jobs.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Automations Session Retention`},help:{"v1-4wagu6-7e":"Controls how long completed automation run sessions are kept before pruning (`24h`, `7d`, `1h30m`, or `false` to disable pruning; a zero duration such as `0h` also disables; default: `24h`). Use shorter retention to reduce storage growth on high-frequency schedules."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Skip Missed Recurring Automations`},help:{"v1-w9wfmo-66":`Skips missed recurring cron/every slots at Gateway startup and schedules their next future occurrence instead of catching up. Default: false. Enable to avoid stale reminders after downtime; one-shot at jobs still catch up.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Automations Webhook SSRF Policy`},help:{"v1-1xlfqnu-5h":`SSRF policy applied to every outbound automation webhook. Private, loopback, link-local, and internal targets stay blocked unless this policy explicitly allows them. Keep unset for strict delivery.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Automations Webhook Allowed Hostnames`},help:{"v1-1i94hyz-3n":`Exact hostnames or IP literals allowed for automation webhook delivery, including otherwise blocked targets. Keep the list minimal.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Automations Webhook Allow IPv6 Unique Local Range`},help:{"v1-rke0oj-3b":`Allows automation webhooks to IPv6 Unique Local Addresses (fc00::/7). Use only with trusted fake-IP proxy environments.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Automations Webhook Allow RFC 2544 Benchmark Range`},help:{"v1-x1usg4-3h":`Allows automation webhooks to RFC 2544 benchmark-range IPs (198.18.0.0/15). Use only with trusted fake-IP proxy environments.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Automations Webhook Blocked Hostnames`},help:{"v1-16cv1ic-6a":`Hostname patterns denied before DNS and allow rules for automation webhook delivery. Supports exact hosts and "*.example.com" for subdomains only; add "example.com" separately to block the apex. Empty or unset adds no denials.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Automations Webhook Dangerously Allow Private Network`},help:{"v1-1n9710c-3t":`Allows automation webhooks to private and internal network targets. Keep disabled unless every configured webhook destination is trusted.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Automations Webhook Bearer Token`},help:{"v1-1l90hxg-5l":`Bearer token attached to automation webhook POST deliveries when webhook mode is used. Prefer secret/env substitution and rotate this token regularly if shared webhook endpoints are internet-reachable.`}},desktop:{label:{"v1-rs698z-7":`Desktop`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Local Desktop`},help:{"v1-99weio-30":`Desktop observation for paired nodes, or the experimental Gateway host source, backed by a local VNC server.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Desktop Sharing`},help:{"v1-m9lbcj-83":`Enables this machine's desktop source. Paired macOS, Windows, and Linux nodes default to enabled; an explicit desktop-app sharing preference takes precedence. The Gateway host Labs source defaults to disabled and applies changes live. Restart a paired node after changing its desktop config.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Managed Linux Host Desktop`},help:{"v1-1r7n22m-49":`Runs and supervises a loopback-only headless TigerVNC/XFCE desktop on Linux. An explicit port or existing default-port VNC server still takes precedence.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Local VNC Password File`},help:{"v1-1m5lsox-37":`Absolute path to the VNC password file. Omit on macOS to enter account credentials when opening the desktop viewer.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Local VNC Port`},help:{"v1-1ku4w9b-2b":`Loopback RFB port of an already-running VNC server on this machine (default: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostics`},help:{"v1-1d5rnym-5p":`Diagnostics controls for targeted tracing, telemetry export, and cache inspection during debugging. Keep baseline diagnostics minimal in production and enable deeper signals only when investigating issues.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Cache Trace`},help:{"v1-10523zm-5b":`Cache-trace logging settings for observing cache decisions and payload context in embedded runs. Enable this temporarily for debugging and disable afterward to reduce sensitive log footprint.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Cache Trace Enabled`},help:{"v1-2c1umi-1v":`Log cache trace snapshots for embedded agent runs (default: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostics Enabled`},help:{"v1-a46pxt-4h":`Master toggle for diagnostics instrumentation output in logs and telemetry wiring paths. Defaults to enabled; set false only in tightly constrained environments.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Diagnostics Flags`},help:{"v1-x4w5ok-33":`Enable targeted diagnostics logs by flag (e.g. ["telegram.http"]). Supports wildcards like "telegram.*" or "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`OpenTelemetry export settings for traces, metrics, and logs emitted by gateway components. Use this when integrating with centralized observability backends and distributed tracing pipelines.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`OpenTelemetry Content Capture`},help:{"v1-19tid4t-2t":`Opt-in OTEL span content capture. Defaults to off; true captures non-system message and tool content.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry Enabled`},help:{"v1-193bm0-5b":`Enables OpenTelemetry export pipeline for traces, metrics, and logs based on configured endpoint/protocol settings. Keep disabled unless your collector endpoint and auth are fully configured.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry Endpoint`},help:{"v1-4rrd1x-4y":`Collector endpoint URL used for OpenTelemetry export transport, including scheme and port. Use a reachable, trusted collector endpoint and monitor ingestion errors after rollout.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry Flush Interval (ms)`},help:{"v1-1moqogc-53":`Interval in milliseconds for periodic telemetry flush from buffers to the collector. Increase to reduce export chatter, or lower for faster visibility during active incident response.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry Headers`},help:{"v1-s26t2a-52":`Additional HTTP request headers sent with OpenTelemetry export requests, often used for tenant auth or routing. Keep secrets in env-backed values and avoid unnecessary header sprawl.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry Logs Enabled`},help:{"v1-12wo6rv-4k":`Enable log signal export through OpenTelemetry in addition to local logging sinks. Use this when centralized log correlation is required across services and agents.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry Logs Endpoint`},help:{"v1-1vgzldu-40":`Signal-specific OTLP/HTTP logs endpoint. When set, this overrides diagnostics.otel.endpoint and OTEL_EXPORTER_OTLP_ENDPOINT for log export only.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry Logs Exporter`},help:{"v1-9bzywd-5q":`Log export sink for diagnostics.otel.logs. Use "otlp" for the configured OTLP logs endpoint, "stdout" for one JSON record per stdout line in container log pipelines, and "both" when both sinks are required.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`OpenTelemetry Metric Name Prefix`},help:{"v1-1j1dptx-b2":`Replaces the default "testclaw." prefix on Assistant-owned metric names. Use an empty string to remove the prefix, or up to 128 ASCII letters, digits, underscores, dots, hyphens, and slashes starting with a letter. Include any separator you need, for example "acme."; standard gen_ai.* metric names are unchanged. Changing this value requires updating dashboards and alerts that query the old names.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry Metrics Enabled`},help:{"v1-13r4cf4-4x":`Enable metrics signal export to the configured OpenTelemetry collector endpoint. Keep enabled for runtime health dashboards, and disable only if metric volume must be minimized.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetry Metrics Endpoint`},help:{"v1-qlfh7x-47":`Signal-specific OTLP/HTTP metrics endpoint. When set, this overrides diagnostics.otel.endpoint and OTEL_EXPORTER_OTLP_ENDPOINT for metrics export only.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry Protocol`},help:{"v1-142ns2c-5e":`OTel transport protocol for telemetry export. Only "http/protobuf" is accepted; run "testclaw doctor --fix" to repair a persisted legacy "grpc" value or get source-specific manual-edit guidance.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetry Trace Sample Rate`},help:{"v1-brcwep-50":`Trace sampling rate (0-1) controlling how much trace traffic is exported to observability backends. Lower rates reduce overhead/cost, while higher rates improve debugging fidelity.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry Service Name`},help:{"v1-1hpiqon-5d":`Service name reported in telemetry resource attributes to identify this gateway instance in observability backends. Use stable names so dashboards and alerts remain consistent over deployments.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry Traces Enabled`},help:{"v1-j7zrrp-4s":`Enable trace signal export to the configured OpenTelemetry collector endpoint. Keep enabled when latency/debug tracing is needed, and disable if you only want metrics/logs.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry Traces Endpoint`},help:{"v1-8yw5p1-43":`Signal-specific OTLP/HTTP trace endpoint. When set, this overrides diagnostics.otel.endpoint and OTEL_EXPORTER_OTLP_ENDPOINT for trace export only.`}},discovery:{label:{"v1-l2sr05-9":`Discovery`},help:{"v1-1sqleij-4w":`Service discovery settings for local mDNS advertisement and optional wide-area presence signaling. Keep discovery scoped to expected networks to avoid leaking service metadata.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS Discovery`},help:{"v1-vtbyyq-4w":`mDNS discovery configuration group for local network advertisement and discovery behavior tuning. Keep minimal mode for routine LAN discovery unless extra metadata is required.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS Discovery Mode`},help:{"v1-1p28pd5-2m":`mDNS broadcast mode ("minimal" default, "full" includes cliPath/sshPort, "off" disables mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Wide-area Discovery`},help:{"v1-1akkqjm-53":`Wide-area discovery configuration group for exposing discovery signals beyond local-link scopes. Enable only in deployments that intentionally aggregate gateway presence across sites.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Wide-area Discovery Domain`},help:{"v1-1ttukjk-4m":`Optional unicast DNS-SD domain for wide-area discovery, such as testclaw.internal. Use this when you intentionally publish gateway discovery beyond local mDNS scopes.`}},env:{label:{"v1-1zc80q-b":`Environment`},help:{"v1-1ao5po6-55":`Environment import and override settings used to supply runtime variables to the gateway process. Use this section to control shell-env loading and explicit variable injection behavior.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Shell Environment Import`},help:{"v1-1gw487t-4y":`Shell environment import controls for loading variables from your login shell during startup. Keep this enabled when you depend on profile-defined secrets or PATH customizations.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Shell Environment Import Enabled`},help:{"v1-5tiuup-5u":`Enables loading environment variables from the user shell profile during startup initialization. Keep enabled for developer machines, or disable in locked-down service environments with explicit env management.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Shell Environment Import Timeout (ms)`},help:{"v1-nsk2yf-5c":`Maximum time in milliseconds allowed for shell environment resolution before fallback behavior applies. Use tighter timeouts for faster startup, or increase when shell initialization is heavy.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Environment Variable Overrides`},help:{"v1-12u1zp3-5n":`Explicit key/value environment variable overrides merged into runtime process environment for Assistant. Use this for deterministic env configuration instead of relying only on shell profile side effects.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Gateway runtime surface for bind mode, auth, control UI, remote transport, and operational safety controls. Keep conservative defaults unless you intentionally expose the gateway beyond trusted local interfaces.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Gateway Allow x-real-ip Fallback`},help:{"v1-1wr3qmw-4c":`Enables x-real-ip fallback when x-forwarded-for is missing in proxy scenarios. Keep disabled unless your ingress stack requires this compatibility behavior.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway Auth`},help:{"v1-70b6ni-50":`Authentication policy for gateway HTTP/WebSocket access including mode, credentials, trusted-proxy behavior, and rate limiting. Keep auth enabled for every non-loopback deployment.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Gateway Auth Allow Tailscale Identity`},help:{"v1-vqtmgw-53":`Allows trusted Tailscale identity paths to satisfy gateway auth checks when configured. Use this only when your tailnet identity posture is strong and operator workflows depend on it.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Gateway Identity Scope Grants`},help:{"v1-1h0zxy7-5n":`Maps verified trusted-proxy or Tailscale identities to connection-only operator scope grants. Email keys match case-insensitively; grants augment device scopes before the connection scope cap is applied.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway Auth Mode`},help:{"v1-j8rodq-9t":`Gateway auth mode: "none", "token", "password", or "trusted-proxy" depending on your edge architecture. Token/password mode selects the configured secret (gateway.auth.token or gateway.auth.password); clients may send it in either connect auth field. Use token/password for direct exposure, and trusted-proxy only behind hardened identity-aware proxies.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway Password`},help:{"v1-1ndt0u2-4g":`Shared secret selected by gateway.auth.mode=password. Clients may send it in either auth.token or auth.password. Password mode is required for Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Gateway Auth Rate Limit`},help:{"v1-1kstr42-54":`Login/auth attempt throttling controls to reduce credential brute-force risk at the gateway boundary. Keep enabled in exposed environments and tune thresholds to your traffic baseline.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gateway Token`},help:{"v1-16i7cxs-5q":`Shared secret selected by gateway.auth.mode=token, the default for new local onboarding. Clients may send it in either auth.token or auth.password. Non-loopback binds require an enabled authentication mode.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway Trusted Proxy Auth`},help:{"v1-12fsi5d-58":`Trusted-proxy auth header mapping for upstream identity providers that inject user claims. Use only with known proxy CIDRs and strict header allowlists to prevent spoofed identity headers.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Cloudflare Access OIDC GitHub Identity`},help:{"v1-1puth4k-6t":`Optional verified GitHub identity from a selected Cloudflare Access OIDC provider. Requires the standard Access email and assertion headers. Missing claims keep email-only profiles; existing profile roles and co-author preferences are preserved.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`GitHub Account ID Claim`},help:{"v1-pcaaw7-57":`Exact forwarded OIDC claim whose value is a verified positive decimal-string GitHub account ID. Configure Access to forward it in oidc_fields; never use an unverified user-editable claim.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access Issuer`},help:{"v1-gykv03-56":`Exact HTTPS origin of the trusted Cloudflare Access team, such as https://example.cloudflareaccess.com, without a trailing slash. Claims from other issuers do not supply GitHub identity.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDC Provider ID`},help:{"v1-kbyo5w-44":`Exact Access identity-provider ID for the trusted OIDC integration. A provider display name or a matching claim name alone does not establish trust.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Trusted Proxy Device Auto-Approval`},help:{"v1-1u23sne-6z":`Optional policy for automatically approving new browser and native UI operator devices and same-key scope upgrades after trusted-proxy authentication. Grants are capped by deviceAutoApprove.scopes and the proxy's x-testclaw-scopes header when present.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Trusted Proxy Device Auto-Approval Enabled`},help:{"v1-1nntwls-78":`Automatically approves new browser and native UI operator devices and same-key scope upgrades after the reverse proxy authenticates an allowed user. Default: false. Enable only when the proxy identity boundary is strong enough to replace manual device pairing.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Trusted Proxy Device Auto-Approval Scopes`},help:{"v1-raeila-g3":`Maximum scopes granted to auto-approved operator devices. Defaults to operator.read, operator.write, operator.approvals, and operator.questions. Requested scopes are capped to this list; requests without scopes receive this list. When unset, auto-approval also adds operator.questions for older UI clients; an explicit list is never widened. Explicitly listing operator.admin lets every proxy-authenticated user auto-approve full admin and makes scope-less requests receive full admin automatically; it also triggers a critical security audit finding and Gateway startup warning.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway Bind Mode`},help:{"v1-1unqude-4y":`Network bind profile: "auto", "lan", "loopback", "custom", or "tailnet" to control interface exposure. Keep "loopback" for local-only operation; "auto" can expose all interfaces.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI Agents`},help:{"v1-1qqo8m2-5a":`Control UI discovery for external CLI session engines exposed by the Gateway session catalog. Enabled by default; disable to prevent starting those engines from the new-session model picker.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI Agents Enabled`},help:{"v1-ufu7fx-8p":`Shows catalog-backed CLI agents in the Control UI new-session model picker when true (default: true). Set false to disable CLI agents and native CLI session creation. Only catalogs that advertise session creation are listed, and the picker stays hidden when the Gateway does not advertise session catalog support.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Control UI hosting settings including enablement, pathing, and browser-origin/auth hardening behavior. Keep UI exposure minimal and pair with strong auth controls before internet-facing deployments.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Control UI Allowed Origins`},help:{"v1-1stgitk-9i":`Allowed browser origins for Control UI/WebChat websocket connections (full origins only, e.g. https://control.example.com). Required for non-loopback Control UI deployments unless dangerous Host-header fallback is explicitly enabled. Setting ["*"] means allow any browser origin and should be avoided outside tightly controlled local testing.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Allow External Control UI Embed URLs`},help:{"v1-1l61zj8-6s":`DANGEROUS toggle that allows hosted embeds to load absolute external http(s) URLs. Keep this off unless your Control UI intentionally embeds trusted third-party pages; hosted /__testclaw__/canvas and /__testclaw__/a2ui documents do not need it.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Automatically Fetch Link Favicons`},help:{"v1-bn9u34-ag":`Fetch link favicons and browser-tab social previews through the Gateway (default on). Browser-tab cards load public page metadata and declared images without browser cookies or site credentials. All requests use strict SSRF checks and bounded HTML/image processing. Set false to disable both automatic favicon and page-preview fetches; live browser screenshots are unaffected.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Control UI Base Path`},help:{"v1-mw10gr-1w":`Optional URL prefix where the Control UI is served (e.g. /testclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Control UI Community Invitation`},help:{"v1-1rz3zsx-73":`Show the Discord community invitation in the Control UI served by this Gateway (default on). Set false to hide it for every browser using this UI deployment. Changes apply after browser refresh or reconnect; re-enabling preserves browser-local dismissals.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Dangerously Allow Host-Header Origin Fallback`},help:{"v1-1t1qi4c-7v":`DANGEROUS toggle that enables Host-header based origin fallback for Control UI/WebChat websocket checks. This mode is supported when your deployment intentionally relies on Host-header origin policy; explicit gateway.controlUi.allowedOrigins remains the recommended hardened default.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Control UI Embed Sandbox Mode`},help:{"v1-d54l3a-7c":'Iframe sandbox policy for hosted Control UI embeds. "strict" disables scripts, "scripts" allows interactive embeds while keeping origin isolation (default), and "trusted" adds `allow-same-origin` for same-site documents that intentionally need stronger privileges.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI Enabled`},help:{"v1-1hhyymc-4w":`Enables serving the gateway Control UI from the gateway HTTP process when true. Keep enabled for local administration, and disable when an external control surface replaces it.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI Environment`},help:{"v1-paarso-4n":`Optional public environment identity shown in the Control UI stripe, agent avatar, label pills, browser title, and favicon. Omit it to preserve the default appearance.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Control UI Environment Color`},help:{"v1-mp6cta-2i":`Named environment color ramp: teal, amber, purple, coral, pink, blue, green, red, or gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Control UI Environment Label`},help:{"v1-1njve3z-3z":`Environment label displayed in the Control UI and browser tab; surrounding whitespace is trimmed and the label must contain 1 to 24 characters.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Experimental Control UI Features`},help:{"v1-1qobi2m-3g":`Opt-in Control UI experiments. These capabilities may change between releases and remain disabled unless explicitly enabled.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Custom Plugin UI`},help:{"v1-108u6ts-9e":`Allow user-installed plugins to execute native JavaScript in the Control UI (default: false). Bundled plugin views remain available. Custom UI shares the signed-in operator's Gateway permissions; enable only for trusted plugins. Changes apply without a Gateway restart. Reload open Control UI pages to clear previously loaded plugin code.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Control UI GitHub Service Credential`},help:{"v1-1p31phh-d6":`SecretRef-backed service credential for Control UI project discovery and GitHub hover previews without a managed identity. Hover previews prefer the selected agent's configured GitHub identity, inheriting the system identity when there is no override. Prefer explicit configuration for clear service ownership. Omit it to retain the GH_TOKEN/GITHUB_TOKEN fallback from the shared Gateway process environment. An explicitly configured but unavailable credential fails closed.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Control UI Assets Root`},help:{"v1-elck04-25":`Optional filesystem root for Control UI assets (defaults to dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Control UI Session Observer`},help:{"v1-1ahs80-8a":`Produce live session status digests for subscribed Control UI clients with each agent's utility model (default on). Set false to disable observer model calls gateway-wide; setting agents.defaults.utilityModel to an empty string disables utility-model observation for agents that do not override it.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Gateway Custom Bind Host`},help:{"v1-lwjcyo-4d":`IPv4 address used for a custom bind. Specific IPv4s also require the same Gateway port on 127.0.0.1; avoid 0.0.0.0 unless all-interface exposure is required.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`Gateway HTTP API`},help:{"v1-ebtex7-4j":`Gateway HTTP API configuration grouping endpoint toggles and transport-facing API exposure controls. Keep only required endpoints enabled to reduce attack surface.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Gateway HTTP Endpoints`},help:{"v1-1a0r104-55":`HTTP endpoint feature toggles under the gateway API surface for compatibility routes and optional integrations. Enable endpoints intentionally and monitor access patterns after rollout.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`OpenAI Chat Completions Endpoint`},help:{"v1-1271mpb-2b":"Enable the OpenAI-compatible `POST /v1/chat/completions` endpoint (default: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`OpenAI Chat Completions Image Limits`},help:{"v1-xgscw1-20":"Image fetch/validation controls for OpenAI-compatible `image_url` parts."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`OpenAI Chat Completions Image MIME Allowlist`},help:{"v1-1guijf3-1t":"Allowed MIME types for `image_url` parts (case-insensitive list)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`OpenAI Chat Completions Allow Image URLs`},help:{"v1-55cb3n-47":"Allow server-side URL fetches for `image_url` parts (default: false; data URIs remain supported). Set this to `false` to disable URL fetching entirely."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`OpenAI Chat Completions Image Max Bytes`},help:{"v1-d920yx-1s":"Max bytes per fetched/decoded `image_url` image (default: 10MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions Image Max Redirects`},help:{"v1-1enujsk-1z":"Max HTTP redirects allowed when fetching `image_url` URLs (default: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions Image Timeout (ms)`},help:{"v1-89w2b9-1x":"Timeout in milliseconds for `image_url` URL fetches (default: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions Image URL Allowlist`},help:{"v1-n4hlt1-4r":"Optional hostname allowlist for `image_url` URL fetches; supports exact hosts and `*.example.com` wildcards. Empty or omitted lists mean no hostname allowlist restriction."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Gateway HTTP Security Headers`},help:{"v1-n8z1hb-44":`Optional HTTP response security headers applied by the gateway process itself. Prefer setting these at your reverse proxy when TLS terminates there.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Strict Transport Security Header`},help:{"v1-1buwhc3-3v":`Value for the Strict-Transport-Security response header. Set only on HTTPS origins that you fully control; use false to explicitly disable.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway Mode`},help:{"v1-nfjirv-5m":`Gateway operation mode: "local" runs channels and agent runtime on this host, while "remote" connects through remote transport. Keep "local" unless you intentionally run a split remote gateway topology.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Gateway Node Skills Enabled`},help:{"v1-1xwu6at-3g":`Accept skills published by paired nodes while they are connected (default: true). Set false to ignore node-published skills.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Gateway Node Browser Mode`},help:{"v1-oeu1nc-69":`Node browser routing ("auto" = prefer the host browser, use a single connected browser node when local capability is unavailable; "manual" = require an explicit node selection or configured pin; "off" = disable node routing).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Gateway Node Browser Pin`},help:{"v1-1cykty2-1p":`Pin browser routing to a specific node id or name (optional).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Gateway Node Allowlist (Extra Commands)`},help:{"v1-zw8asn-5m":"Extra node.invoke commands to allow beyond the gateway defaults (array of command strings). Enabling dangerous commands here is a security-sensitive override and is flagged by `testclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Gateway Node Denylist`},help:{"v1-u7c8wx-53":"Node command names to block even if present in node claims or default allowlist (exact command-name matching only, e.g. `system.run`; does not inspect shell text inside that command)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Gateway Node Pairing`},help:{"v1-gldsi2-4s":`Node pairing policy settings. SSH-verified auto-approval is enabled by default; CIDR auto-approval stays disabled unless explicit trusted CIDR/IP allowlists are configured.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Gateway Node Pairing Auto-Approve CIDRs`},help:{"v1-1m6jsxj-6x":`Opt-in CIDR/IP allowlist for auto-approving first-time node-role device pairing with no requested scopes. Disabled when unset. Operator, browser, Control UI, and any role, scope, metadata, or public-key upgrade pairing still require manual approval.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Gateway Node Pairing Auto-Approve Local`},help:{"v1-glzm36-41":`Silently approve trusted local pairing and access upgrades (default: true); set false to trade convenience for explicit approval of every device.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Gateway Node Pairing SSH Verification`},help:{"v1-evfjpe-ct":"SSH-verified auto-approval for first-time node-role device pairing (default: enabled). The gateway SSHes back to the pairing host (BatchMode, strict host keys) and approves only when the remote `testclaw node identity` output matches the pending device key. Set false to disable SSH verification (independent of autoApproveCidrs, which stays active); for manual-only pairing also unset autoApproveCidrs. Pass an object to override user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Gateway Node Plugin Tools`},help:{"v1-1c24iq3-28":`Controls whether paired nodes may publish agent-visible plugin tool descriptors.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Gateway Node Plugin Tools Enabled`},help:{"v1-14lgfu6-47":`Accept agent-visible plugin tool descriptors published by paired nodes (default: true). Set false to ignore and remove all node-published plugin tools.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway Port`},help:{"v1-for8t5-54":`TCP port used by the gateway listener for API, control UI, and channel-facing ingress paths. Use a dedicated port and avoid collisions with reverse proxies or local developer services.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway Portals`},help:{"v1-1v2lkw9-1c":`Portal publication and private ingress settings.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Private Portal Ingress`},help:{"v1-20w4gq-69":`Optional operator-managed private HTTPS wildcard reverse proxy. Forward original Host, paths, and WebSocket upgrades to the dedicated loopback listener. Portal bearer authentication remains required. Requires Gateway restart.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Portal Wildcard Domain`},help:{"v1-1ipbfad-53":`Bare DNS domain for random portal subdomains (for example previews.example.net). Configure wildcard DNS and HTTPS privately; do not share the Gateway or Control UI hostname namespace.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Portal Ingress Loopback Port`},help:{"v1-1mb98cv-4g":`Dedicated loopback HTTP port receiving the private wildcard HTTPS proxy. Must differ from the Gateway port. This is the backend port, not the public HTTPS port.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Gateway Public Origin`},help:{"v1-17vekvx-87":`Externally reachable HTTPS origin of the Gateway. HTTP is allowed only for localhost, 127.0.0.1, or [::1]. Per-requester MCP OAuth uses it to build the callback URL at /oauth/mcp/callback; channel session links and plugin-generated viewer links use it to reach the Control UI and Gateway routes.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway Push Delivery`},help:{"v1-h23oz7-5s":`Push-delivery settings used by the gateway when it needs to wake or notify paired devices. Configure relay-backed APNs here for official iOS builds; direct APNs auth remains env-based for local/manual builds.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway APNs Delivery`},help:{"v1-4bbafr-4e":`APNs delivery settings for iOS devices paired to this gateway. Use relay settings for official App Store builds that register through the external push relay.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway APNs Relay`},help:{"v1-1rp2l1h-6x":`External relay settings for relay-backed APNs sends. The gateway uses the hosted Assistant relay by default, or this custom relay for push.test, wake nudges, and reconnect wakes after a paired official iOS build publishes a relay-backed registration.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Gateway APNs Relay Base URL`},help:{"v1-1o8mgnq-69":`Optional custom base HTTPS URL for the external APNs relay service used by official App Store iOS builds. Keep this aligned with the relay URL baked into the iOS build so registration and send traffic hit the same deployment.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Gateway APNs Relay Timeout (ms)`},help:{"v1-a0jkb1-4z":`Timeout in milliseconds for relay send requests from the gateway to the APNs relay (default: 10000). Increase for slower relays or networks, or lower to fail wake attempts faster.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Config Reload`},help:{"v1-d02mvq-4w":`Live config-reload policy for how edits are applied and when full restarts are triggered. Keep hybrid behavior for safest operational updates unless debugging reload internals.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Config Reload Mode`},help:{"v1-1q1etcf-3m":`Controls how config edits are applied: "off" ignores live edits and "hybrid" applies hot-safe changes then restarts when required.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Remote Gateway`},help:{"v1-6xv7gd-5a":`Remote gateway connection settings for direct or SSH transport when this instance proxies to another runtime host. Use remote mode only when split-host operation is intentionally configured.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Remote Gateway Edge Auth Headers`},help:{"v1-jg9p7d-5o":`Secret-backed HTTP headers presented to an identity-aware proxy in front of the configured remote Gateway. Headers are sent only to the exact gateway.remote.url origin over WSS and never follow redirects.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Remote Gateway Password`},help:{"v1-16jc0yx-7y":`Shared secret sent in the password field to authenticate this client to a remote gateway. The server's gateway.auth.mode selects its configured secret; either client token or password field is accepted. Keep this secret managed externally and avoid plaintext values in committed config.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Remote Gateway SSH Host-Key Policy`},help:{"v1-7qoxtb-49":`macOS SSH host-key verification policy. "strict" requires an already trusted host key; "openssh" explicitly delegates to effective OpenSSH configuration.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Remote Gateway SSH Identity`},help:{"v1-hz2hsm-1f":`Optional SSH identity file path (passed to ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Remote Gateway SSH Target`},help:{"v1-85w39w-2t":`Remote gateway over SSH (tunnels the gateway port to localhost). Format: user@host or user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Remote Gateway TLS Fingerprint`},help:{"v1-1ri16lk-23":`Expected sha256 TLS fingerprint for the remote gateway (pin to avoid MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Remote Gateway Token`},help:{"v1-1pb9q8w-7v":`Shared secret sent in the token field to authenticate this client to a remote gateway. The server's gateway.auth.mode selects its configured secret; either client token or password field is accepted. Store via secret/env substitution and rotate alongside remote gateway auth changes.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Remote Gateway Transport`},help:{"v1-1acfs7m-54":`Remote connection transport: "direct" uses configured URL connectivity, while "ssh" tunnels through SSH. Use SSH when you need encrypted tunnel semantics without exposing remote ports.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`Remote Gateway URL`},help:{"v1-va7exe-1b":`Remote Gateway WebSocket URL (ws:// or wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Gateway Operator Roles`},help:{"v1-b59sc5-6w":`Optional profile-bound operator roles for team Gateways. Each named role controls access to other people's sessions, sandbox isolation, session and run agents, and granted operator scopes; omitting this section preserves existing operator behavior.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Default Operator Role`},help:{"v1-1v8add8-4u":`Required role assigned to authenticated profiles without a valid explicit assignment whenever operator roles are configured. Its name must match a configured role definition.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Operator Role Definitions`},help:{"v1-uv91an-53":`Nonempty administrator-named role definitions bundling the closed session-sharing, sandbox-isolation, agent-access, and operator-scope policies applied to authenticated user profiles.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Operator Role Definition`},help:{"v1-p8tfws-6q":`One named operator role. Every definition must explicitly provide its session-sharing policy, allowed session and run agents, and operator-scope ceiling, and can require sandbox isolation for newly created sessions and a plugin access policy.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Operator Role Access Policy Plugin`},help:{"v1-1gq4q08-9n":`Optional exact plugin ID whose Gateway access policy must authorize this role. Access is denied when the plugin is missing, disabled, fails to load, or supplies no current authority. Unavailable plugin IDs remain valid configuration so independent staff roles and the Gateway owner can repair access. Omitting this field adds no plugin dependency.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Operator Role Allowed Agents`},help:{"v1-fvun18-4v":`Agents available when this role creates sessions or starts runs: set "*" to allow every agent, list agent IDs to allow only those agents, or use an empty list to disable both.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Operator Role Sandbox Isolation`},help:{"v1-sknx21-66":`Execution isolation for newly created sessions: "inherit" (default) uses the agent policy; "required" permanently requires a sandbox, even when the agent sandbox mode is off, and fails closed if the backend is unavailable.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Operator Role Scope Ceiling`},help:{"v1-1selr2i-4s":`Closed list of operator scopes granted as this role's maximum connection authority. Requested, paired, identity-granted, and upgraded scopes are intersected with this list.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Operator Role Session Access`},help:{"v1-hsoiop-45":`Session-sharing permissions granted to this role for sessions created by other authenticated people; a person's own sessions remain owner-accessible.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Operator Role Access to Other Sessions`},help:{"v1-vf8umx-5r":`Access to other people's sessions: "none" hides them, "view" allows reading, "suggest" permits the suggestion flow, and "write" permits participation. Explicit session membership can grant additional access.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway Tailscale`},help:{"v1-6ar9o-4x":`Tailscale integration settings for Serve/Funnel exposure and lifecycle handling on gateway start/exit. Keep off unless your deployment intentionally relies on Tailscale ingress.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway Tailscale Mode`},help:{"v1-6l2099-5a":`Tailscale publish mode: "off", "serve", or "funnel" for private or public exposure paths. Use "serve" for tailnet-only access and "funnel" only when public internet reachability is required.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Gateway Tailscale External Funnel Migration Guard`},help:{"v1-rg34s7-7q":`Deprecated migration guard for mode='serve'. If an external Funnel still targets the ordinary Gateway listener, Assistant leaves exposure unchanged and warns that only plugin-authenticated webhooks remain usable until password auth is configured and mode is migrated to 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Operator Terminal`},help:{"v1-18f5rgm-8b":`Operator terminal served to Control UI and mobile clients: a PTY-backed shell on the gateway host, restricted to admin-scope operator sessions. It starts in the target agent's workspace and is refused for fully-sandboxed agents (sandbox.mode 'all') rather than handing back an unconfined host shell.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Operator Terminal Detached Session Timeout`},help:{"v1-k6qbgr-9e":`Seconds a terminal session survives after its connection drops (laptop sleep, page reload), staying reattachable via terminal.attach with its recent output replayed. Set 0 to kill sessions the moment the connection drops. Default: 300 (5 minutes). Detached sessions keep running their commands, so shorten this on shared or exposed hosts.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Operator Terminal Enabled`},help:{"v1-1nez06v-7p":`Enables the operator terminal for admin-scope clients (default: true). This exposes a browser/mobile shell with the gateway process environment; set false to opt out on deployments where admin operators should not get a host shell. Changes apply without restarting the Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Operator Terminal Shell`},help:{"v1-19mfe6t-5i":`Shell executable the operator terminal launches. Leave unset to use the host login shell ($SHELL on Unix, %ComSpec% on Windows), or pin an explicit interpreter for a consistent operator environment.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway TLS`},help:{"v1-1dx77dq-4z":`TLS certificate and key settings for terminating HTTPS directly in the gateway process. Use explicit certificates in production and avoid plaintext exposure on untrusted networks.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway TLS Auto-Generate Cert`},help:{"v1-1ld6uiu-4w":`Auto-generates a local TLS certificate/key pair when explicit files are not configured. Use only for local/dev setups and replace with real certificates for production traffic.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Gateway TLS CA Path`},help:{"v1-andqlu-52":`Optional CA bundle path for client verification or custom trust-chain requirements at the gateway edge. Use this when private PKI or custom certificate chains are part of deployment.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Gateway TLS Certificate Path`},help:{"v1-1wznaof-4q":`Filesystem path to the TLS certificate file used by the gateway when TLS is enabled. Use managed certificate paths and keep renewal automation aligned with this location.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`Gateway TLS Enabled`},help:{"v1-ykhwp0-4o":`Enables TLS termination at the gateway listener so clients connect over HTTPS/WSS directly. Keep enabled for direct internet exposure or any untrusted network boundary.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Gateway TLS Key Path`},help:{"v1-15knri0-4i":`Filesystem path to the TLS private key file used by the gateway when TLS is enabled. Keep this key file permission-restricted and rotate per your security policy.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Gateway Tool Exposure Policy`},help:{"v1-1ffol26-5a":`Gateway-level tool exposure allow/deny policy that can restrict runtime tool availability independent of agent/tool profiles. Use this for coarse emergency controls and production hardening.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Gateway Tool Allowlist`},help:{"v1-163khb1-4y":`Explicit gateway-level tool allowlist when you want a narrow set of tools available at runtime. Use this for locked-down environments where tool scope must be tightly controlled.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Gateway Tool Denylist`},help:{"v1-1lhssnf-4o":`Explicit gateway-level tool denylist to block risky tools even if lower-level policies allow them. Use deny rules for emergency response and defense-in-depth hardening.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Gateway Trusted Proxy CIDRs`},help:{"v1-n5zcvf-4f":`CIDR/IP allowlist of upstream proxies permitted to provide forwarded client identity headers. Keep this list narrow so untrusted hops cannot impersonate users.`}},hooks:{label:{"v1-j9ywl7-5":`Hooks`},help:{"v1-18ftjr6-5v":`Inbound webhook automation surface for mapping external events into wake or agent actions in Assistant. Keep this locked down with explicit token/session/agent controls before exposing it beyond trusted networks.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Hooks Allowed Agent IDs`},help:{"v1-hree88-7c":`Allowlist of effective agent IDs that hook requests and mappings are allowed to target, including default-agent routing when agentId is omitted. Use this to constrain automation events to dedicated service agents and reduce blast radius if a hook token is exposed.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Hooks Allowed Session Key Prefixes`},help:{"v1-b346oh-4r":`Allowlist of accepted session-key prefixes for inbound hook requests when caller-provided keys are enabled. Use narrow prefixes to prevent arbitrary session-key injection.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Hooks Allow Request Session Key`},help:{"v1-11n9ps-52":`Allows callers to supply a session key in hook requests when true, enabling caller-controlled routing. Keep false unless trusted integrators explicitly need custom session threading.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Hooks Default Session Key`},help:{"v1-bzdgkn-57":`Fallback session key used for hook deliveries when a request does not provide one through allowed channels. Use a stable but scoped key to avoid mixing unrelated automation conversations.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks Enabled`},help:{"v1-1mixmjf-4n":`Enables the hooks endpoint and mapping execution pipeline for inbound webhook requests. Keep disabled unless you are actively routing external events into the gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail Hook`},help:{"v1-4cibmt-4r":`Gmail push integration settings used for Pub/Sub notifications and optional local callback serving. Keep this scoped to dedicated Gmail automation accounts where possible.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Gmail Hook Account`},help:{"v1-12l1h96-4v":`Google account identifier used for Gmail watch/subscription operations in this hook integration. Use a dedicated automation mailbox account to isolate operational permissions.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Gmail Hook Allow Unsafe External Content`},help:{"v1-1w3gdvs-55":`Allows less-sanitized external Gmail content to pass into processing when enabled. Keep disabled for safer defaults, and enable only for trusted mail streams with controlled transforms.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Gmail Hook Callback URL`},help:{"v1-19fhn6q-4z":`Public callback URL Gmail or intermediaries invoke to deliver notifications into this hook pipeline. Keep this URL protected with token validation and restricted network exposure.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Gmail Hook Include Body`},help:{"v1-14cf1c3-52":`When true, fetch and include email body content for downstream mapping/agent processing. Keep false unless body text is required, because this increases payload size and sensitivity.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Gmail Hook Label`},help:{"v1-9zpdg8-4g":`Optional Gmail label filter limiting which labeled messages trigger hook events. Keep filters narrow to avoid flooding automations with unrelated inbox traffic.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Gmail Hook Max Body Bytes`},help:{"v1-2aaxx1-4b":`Maximum Gmail payload bytes processed per event when includeBody is enabled. Keep conservative limits to reduce oversized message processing cost and risk.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Gmail Hook Model Override`},help:{"v1-1var65t-59":`Optional model override for Gmail-triggered runs when mailbox automations should use dedicated model behavior. Keep unset to inherit agent defaults unless mailbox tasks need specialization.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Gmail Hook Push Token`},help:{"v1-h1vx01-4o":`Shared secret token required on Gmail push hook callbacks before processing notifications. Use env substitution and rotate if callback endpoints are exposed externally.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Gmail Hook Renew Interval (min)`},help:{"v1-pr1z9-49":`Renewal cadence in minutes for Gmail watch subscriptions to prevent expiration. Set below provider expiration windows and monitor renew failures in logs.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Gmail Hook Local Server`},help:{"v1-hom4wq-54":`Local callback server settings block for directly receiving Gmail notifications without a separate ingress layer. Enable only when this process should terminate webhook traffic itself.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Gmail Hook Server Bind Address`},help:{"v1-55bieu-4d":`Bind address for the local Gmail callback HTTP server used when serving hooks directly. Keep loopback-only unless external ingress is intentionally required.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Gmail Hook Server Path`},help:{"v1-1jqhcw4-4h":`HTTP path on the local Gmail callback server where push notifications are accepted. Keep this consistent with subscription configuration to avoid dropped events.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Gmail Hook Server Port`},help:{"v1-1yku7dz-43":`Port for the local Gmail callback HTTP server when serve mode is enabled. Use a dedicated port to avoid collisions with gateway/control interfaces.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail Hook Subscription`},help:{"v1-127h8vg-5b":`Pub/Sub subscription consumed by the gateway to receive Gmail change notifications from the configured topic. Keep subscription ownership clear so multiple consumers do not race unexpectedly.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Gmail Hook Tailscale`},help:{"v1-7jzidp-4l":`Tailscale exposure configuration block for publishing Gmail callbacks through Serve/Funnel routes. Use private tailnet modes before enabling any public ingress path.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Gmail Hook Tailscale Mode`},help:{"v1-vhm395-4u":`Tailscale exposure mode for Gmail callbacks: "off", "serve", or "funnel". Use "serve" for private tailnet delivery and "funnel" only when public internet ingress is required.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Gmail Hook Tailscale Path`},help:{"v1-fr8qi-4m":`Path published by Tailscale Serve/Funnel for Gmail callback forwarding when enabled. Keep it aligned with Gmail webhook config so requests reach the expected handler.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Gmail Hook Tailscale Target`},help:{"v1-1twwxge-47":`Local service target forwarded by Tailscale Serve/Funnel (for example http://127.0.0.1:8787). Use explicit loopback targets to avoid ambiguous routing.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Gmail Hook Thinking Override`},help:{"v1-17owk9q-4z":`Thinking effort override for Gmail-driven agent runs: "off", "minimal", "low", "medium", or "high". Keep modest defaults for routine inbox automations to control cost and latency.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Gmail Hook Pub/Sub Topic`},help:{"v1-iled0e-4p":`Google Pub/Sub topic name used by Gmail watch to publish change notifications for this account. Ensure the topic IAM grants Gmail publish access before enabling watches.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Internal Hooks`},help:{"v1-piq9k-4v":`Internal hook runtime settings for bundled/custom event handlers loaded from module paths. Use this for trusted in-process automations and keep handler loading tightly scoped.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Internal Hooks Enabled`},help:{"v1-1wv0289-4c":`Enables processing for internal hooks and configured entries in the internal hook runtime. Keep disabled unless internal hooks are intentionally configured.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Internal Hook Entries`},help:{"v1-1ovi38l-4o":`Configured internal hook entry records used to register concrete runtime handlers and metadata. Keep entries explicit and versioned so production behavior is auditable.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Internal Hook Loader`},help:{"v1-11re5ph-4p":`Internal hook loader settings controlling where handler modules are discovered at startup. Use constrained load roots to reduce accidental module conflicts or shadowing.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Internal Hook Extra Directories`},help:{"v1-1xfdqxg-4c":`Additional directories searched for internal hook modules beyond default load paths. Keep this minimal and controlled to reduce accidental module shadowing.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Hook Mappings`},help:{"v1-frhp3v-5i":`Ordered mapping rules that match inbound hook requests and choose wake or agent actions with optional delivery routing. Use specific mappings first to avoid broad pattern rules capturing everything.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Hook Mapping Action`},help:{"v1-1r5zt5f-5f":`Mapping action type: "wake" triggers agent wake flow, while "agent" sends directly to agent handling. Use "agent" for immediate execution and "wake" when heartbeat-driven processing is preferred.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Hook Mapping Agent ID`},help:{"v1-l0uioz-4y":`Target agent ID for mapping execution when action routing should not use defaults. Use dedicated automation agents to isolate webhook behavior from interactive operator sessions.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Hook Mapping Allow Unsafe External Content`},help:{"v1-1np9426-57":`When true, mapping content may include less-sanitized external payload data in generated messages. Keep false by default and enable only for trusted sources with reviewed transform logic.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Hook Mapping Delivery Channel`},help:{"v1-oz7pu5-5s":`Delivery channel override for mapping outputs (for example "last", "telegram", "discord", "slack", "signal", "imessage", or "msteams"). Keep channel overrides explicit to avoid accidental cross-channel sends.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Hook Mapping Deliver Reply`},help:{"v1-12tbbam-5o":`Controls whether mapping execution results are delivered back to a channel destination versus being processed silently. Disable delivery for background automations that should not post user-facing output.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Hook Mapping Fan-Out Key`},help:{"v1-1d593op-7e":`Top-level payload array key the mapping fans out over: each element dispatches its own action, and templates or transforms see a payload whose array holds only the current element. The Gmail preset uses forEach: messages so batched pushes dispatch one run per email.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`Hook Mapping ID`},help:{"v1-q1t4zw-57":`Optional stable identifier for a hook mapping entry used for auditing, troubleshooting, and targeted updates. Use unique IDs so logs and config diffs can reference mappings unambiguously.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Hook Mapping Match`},help:{"v1-6u73k2-5a":`Grouping object for mapping match predicates such as path and source before action routing is applied. Keep match criteria specific so unrelated webhook traffic does not trigger automations.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Hook Mapping Match Path`},help:{"v1-1d7dc5j-4k":`Path match condition for a hook mapping, usually compared against the inbound request path. Use this to split automation behavior by webhook endpoint path families.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Hook Mapping Match Source`},help:{"v1-177zgy7-52":`Source match condition for a hook mapping, typically set by trusted upstream metadata or adapter logic. Use stable source identifiers so routing remains deterministic across retries.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Hook Mapping Message Template`},help:{"v1-ggqszl-5c":`Template for synthesizing structured mapping input into the final message content sent to the target action path. Keep templates deterministic so downstream parsing and behavior remain stable.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Hook Mapping Model Override`},help:{"v1-10qyo4j-5e":`Optional model override for mapping-triggered runs when automation should use a different model than agent defaults. Use this sparingly so behavior remains predictable across mapping executions.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Hook Mapping Name`},help:{"v1-zrd9tn-4v":`Human-readable mapping display name used in diagnostics and operator-facing config UIs. Keep names concise and descriptive so routing intent is obvious during incident review.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Hook Mapping Session Key`},help:{"v1-lfnt1n-58":`Explicit session key override for mapping-delivered messages to control thread continuity. Use stable scoped keys so repeated events correlate without leaking into unrelated conversations.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Hook Mapping Session Mode`},help:{"v1-1ggtdze-5k":`Controls mapping session continuity: "isolated" starts a fresh run session, while "persistent" reuses the resolved sessionKey. Keep isolated unless the integration intentionally needs durable context.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Hook Mapping Text Template`},help:{"v1-1rg732b-4y":`Text-only fallback template used when rich payload rendering is not desired or not supported. Use this to provide a concise, consistent summary string for chat delivery surfaces.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Hook Mapping Thinking Override`},help:{"v1-17hq8me-57":`Optional thinking-effort override for mapping-triggered runs to tune latency versus reasoning depth. Keep low or minimal for high-volume hooks unless deeper reasoning is clearly required.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Hook Mapping Timeout (sec)`},help:{"v1-1r44ox2-4i":`Maximum runtime allowed for mapping action execution before timeout handling applies. Use tighter limits for high-volume webhook sources to prevent queue pileups.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Hook Mapping Delivery Destination`},help:{"v1-1p7928e-55":`Destination identifier inside the selected channel when mapping replies should route to a fixed target. Verify provider-specific destination formats before enabling production mappings.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Hook Mapping Transform`},help:{"v1-14igxpm-5m":`Transform configuration block defining module/export preprocessing before mapping action handling. Use transforms only from reviewed code paths and keep behavior deterministic for repeatable automation.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Hook Transform Export`},help:{"v1-atn8v-4b":`Named export to invoke from the transform module; defaults to module default export when omitted. Set this when one file hosts multiple transform handlers.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Hook Transform Module`},help:{"v1-56futq-4v":`Relative transform module path loaded from hooks.transformsDir to rewrite incoming payloads before delivery. Keep modules local, reviewed, and free of path traversal patterns.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Hook Mapping Wake Mode`},help:{"v1-1dzqfnw-59":`Wake scheduling mode: "now" wakes immediately, while "next-heartbeat" defers until the next heartbeat cycle. Use deferred mode for lower-priority automations that can tolerate slight delay.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Hooks Endpoint Path`},help:{"v1-1l9ijzv-4u":"HTTP path used by the hooks endpoint (for example `/hooks`) on the gateway control server. Use a non-guessable path and combine it with token validation for defense in depth."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Hooks Presets`},help:{"v1-dp8m0l-4v":`Named hook preset bundles applied at load time to seed standard mappings and behavior defaults. Keep preset usage explicit so operators can audit which automations are active.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Hooks Auth Token`},help:{"v1-1ihf6mv-82":`Shared bearer token checked by hooks ingress for request authentication before mappings run. Treat holders as full-trust callers for the hook ingress surface, not as a separate non-owner role. Use environment substitution and rotate regularly when webhook endpoints are internet-accessible.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Hooks Transforms Directory`},help:{"v1-1ayj9p0-4t":`Base directory for hook transform modules referenced by mapping transform.module paths. Use a controlled repo directory so dynamic imports remain reviewable and predictable.`}},logging:{label:{"v1-rq08xq-7":`Logging`},help:{"v1-11an9pb-5e":`Logging behavior controls for severity, output destinations, formatting, and sensitive-data redaction. Keep levels and redaction strict enough for production while preserving useful diagnostics.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Audit Ledger`},help:{"v1-1lauvy2-6w":`Bounded metadata-only audit history for operator review. Run and tool records are enabled by default; message lifecycle metadata is a separate privacy-sensitive opt-in. The background writer is best-effort rather than a lossless compliance archive.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Audit Ledger Enabled`},help:{"v1-snknxb-4v":`Records new run, tool, and enabled message audit events. Default: true. Changes apply immediately; accepted writes finish and retained rows remain queryable until they expire.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Execution Identity Audit`},help:{"v1-1ucirwv-5b":`Retains bounded execution-identity attribution for exact-run inspection. Default: false. Requires logging.audit.enabled and applies to newly admitted runs; existing contexts remain unchanged.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Message Audit Scope`},help:{"v1-1yg4lc3-76":`Controls content-free message lifecycle records: "off" (default), "direct" for known direct conversations only, or "all" for direct, group, channel, and unknown conversation kinds. Requires logging.audit.enabled. Changes apply to subsequent lifecycle events.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Console Log Level`},help:{"v1-16badbd-5u":`Console-specific log threshold: "silent", "fatal", "error", "warn", "info", "debug", or "trace" for terminal output control. Use this to keep local console quieter while retaining richer file logging if needed.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Console Log Style`},help:{"v1-d7u0iq-3q":`Console output format style: "pretty" or "json". Use json for machine parsing pipelines and pretty for human-first terminal workflows.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Log File Path`},help:{"v1-16gaitv-4w":`Optional file path for persisted log output in addition to or instead of console logging. Use a managed writable path and align retention/rotation with your operational policy.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Log Level`},help:{"v1-1r5yku0-5o":`Primary log level threshold for runtime logger output: "silent", "fatal", "error", "warn", "info", "debug", or "trace". Keep "info" or "warn" for production, and use debug/trace only during investigation.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Custom Redaction Patterns`},help:{"v1-1esa6eg-7k":`Custom regex strings replace the default string list for log/transcript output and add to safety-boundary UI/tool/diagnostic rules. Built-in form-body, structured-auth, and AWS bare-key protections always apply. Use this to mask deployment-specific tokens and identifiers.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-125aq49-51":`Global MCP server definitions managed by Assistant. Embedded Assistant and other runtime adapters can consume these servers without storing them inside runtime-owned project settings.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP Apps`},help:{"v1-amyd91-38":`MCP Apps UI support. When enabled, configured MCP servers may provide interactive HTML views for their tool results.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps Enabled`},help:{"v1-ghqy98-3w":`Opt-in MCP Apps rendering and app-to-server bridge. Keep disabled unless you trust the configured MCP servers that provide app UI resources.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`MCP Apps Sandbox Origin`},help:{"v1-1sxv3mf-6v":`Optional dedicated public HTTP(S) origin for MCP Apps. Use this behind a reverse proxy or TLS terminator and proxy it only to the configured MCP Apps sandbox port. It must differ from the Control UI origin and must not serve authenticated content.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`MCP Apps Sandbox Port`},help:{"v1-1b8n71l-4p":`Dedicated MCP Apps sandbox listener port. Defaults to the Gateway port plus one. Set an unused port when another local service or Gateway profile already owns that port.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP Servers`},help:{"v1-qu7dmf-42":`Named MCP server definitions. Assistant stores them in its own config and runtime adapters decide which transports are supported at execution time.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP Server Auth`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP Client Certificate`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP Client Key`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP Client Certificate`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP Client Key`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP Projection`},help:{"v1-n22cod-6x":`Assistant projection metadata for Codex app-server threads only. It does not affect ACP sessions or generic Codex harness config. Omit this block to keep the server available to every Codex app-server agent with Codex's default MCP approval behavior.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP Agents`},help:{"v1-1hzgrmk-67":`Optional non-empty Assistant agent ids that should receive this MCP server in Codex app-server thread config. Empty, blank, or invalid lists fail closed; when omitted, the server is projected for all Codex app-server agents.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex MCP Tool Approval`},help:{"v1-15mhiw7-3d":`Codex-native spelling for the same per-server MCP tool approval mode. Prefer defaultToolsApprovalMode in Assistant config.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex MCP Tool Approval`},help:{"v1-y5vsqq-3s":`Optional Codex MCP tool approval mode for this server: "auto", "prompt", or "approve". Use only for MCP servers you intentionally trust.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP Connect Timeout (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP Server Enabled`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP OAuth Auth Profile`},help:{"v1-dwkyxy-5z":`Refresh-capable auth profile id used to inject the current bearer token into this remote MCP server. When set, Assistant resolves and refreshes the profile at runtime and does not project refresh material downstream.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`MCP OAuth Client Metadata URL`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth Identity`},help:{"v1-1ie6ys7-59":`OAuth credential ownership for this server. Omit this field or use "shared" for operator-managed credentials; use "per-requester" to let each authenticated sender connect their own account.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP OAuth Redirect URL`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP OAuth Scope`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`MCP Request Timeout (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP TLS Verification`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP TLS Verification`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`MCP Parallel Tool Calls`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`MCP Parallel Tool Calls`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP Tool Selection`},help:{"v1-10poyzb-4v":`Per-server MCP tool selection. Use include to expose only selected MCP tool names, or exclude to hide selected MCP tool names. Entries accept exact names and simple '*' globs.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Excluded MCP Tools`},help:{"v1-ijrc5y-1u":`Exact MCP tool names or simple '*' globs to hide from this server.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Included MCP Tools`},help:{"v1-89fdfq-3o":`Exact MCP tool names or simple '*' globs to expose from this server. When omitted, all server tools remain eligible unless excluded.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`MCP Session Idle TTL (ms)`},help:{"v1-7t4g2g-87":`Optional idle eviction for Assistant session MCP runtimes in milliseconds. Unset or 0 keeps runtimes alive until session cleanup or Gateway shutdown. Positive values round down; active leases and pending acquisitions prevent eviction. Run-owned runtimes still retire when their one-shot run ends.`}},memory:{label:{"v1-oopaku-6":`Memory`},help:{"v1-1wlx40m-13":`Built-in memory configuration (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Memory Citations Mode`},help:{"v1-1q6dxr5-4u":`Controls citation visibility in replies: "auto" shows citations when useful, "on" always shows them, and "off" hides them. Keep "auto" for a balanced signal-to-noise default.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Memory Search`},help:{"v1-1ukbud1-25":`Vector search over MEMORY.md and memory/*.md (per-agent overrides supported).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Memory Search Embedding Cache`},help:{"v1-d8h2e4-5b":`Caches computed chunk embeddings in SQLite so reindexing and incremental updates run faster (default: true). Keep this enabled unless investigating cache correctness or minimizing disk usage.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Memory Search Document Input Type`},help:{"v1-1ui33sv-5f":"Optional provider-specific `input_type` value for document and indexing memory embeddings. Use this with OpenAI-compatible asymmetric embedding endpoints that require a passage or document label."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Enable Memory Search`},help:{"v1-14f11b9-4t":`Master toggle for memory search indexing and retrieval behavior on this agent profile. Keep enabled for semantic recall, and disable when you want fully stateless responses.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Memory Search Session Index (Experimental)`},help:{"v1-qvhv8z-3i":`Indexes session transcripts into memory search. Keep this advanced override when root and per-agent recall inheritance differ.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Extra Memory Paths`},help:{"v1-ojqokq-7i":`Adds extra directories or .md files to the memory index beyond default memory files. Entries may be path strings or objects with a root-relative glob pattern. When multimodal memory is enabled, matching image/audio files under these paths are also eligible for indexing.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Extra Memory Path`},help:{"v1-b9mbq8-3m":`Sets the extra memory directory or file. Relative paths resolve from the agent workspace; direct file entries are indexed exactly.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Extra Memory Path Pattern`},help:{"v1-j8br1v-4e":`Limits a directory entry to supported files matching this root-relative glob, for example "runbooks/**/*.md". Omit it to scan all supported files recursively.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Memory Search Fallback`},help:{"v1-1r6368w-6p":`Backup provider used when primary embeddings fail: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local", or "none". Set a real fallback for production reliability; use "none" only if you prefer explicit failures.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Memory Search Input Type`},help:{"v1-26vbwe-5u":"Use this optional provider-specific `input_type` value only when the same label should apply to both query and document embedding requests. For asymmetric providers, prefer queryInputType and documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Local Embedding Model Path`},help:{"v1-13ymbnt-5q":"Specifies the local embedding model source for local memory search, such as a GGUF file path or `hf:` URI. Use this only when provider is `local`, and verify model compatibility before large index rebuilds."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Memory Search Model`},help:{"v1-11pohrl-59":`Embedding model override used by the selected memory provider when a non-default model is required. Set this only when you need explicit recall quality/cost tuning beyond provider defaults.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Memory Search Multimodal`},help:{"v1-1jn02s-9e":'Optional multimodal memory settings for indexing image and audio files from configured extra paths. Keep this off unless your embedding model explicitly supports cross-modal embeddings, and set `memory.search.fallback` to "none" while it is enabled. Matching files are uploaded to the configured remote embedding provider during indexing.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Enable Memory Search Multimodal`},help:{"v1-1dk5d7o-7e":`Enables image/audio memory indexing from extraPaths. This currently requires Gemini embedding-2, keeps the default memory roots Markdown-only, disables memory-search fallback providers, and uploads matching binary content to the configured remote embedding provider.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Memory Search Multimodal Max File Bytes`},help:{"v1-1mmdrvk-5d":`Sets the maximum bytes allowed per multimodal file before it is skipped during memory indexing. Use this to cap upload cost and indexing latency, or raise it for short high-quality audio clips.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Memory Search Multimodal Modalities`},help:{"v1-alp4vh-4l":`Selects which multimodal file types are indexed from extraPaths: "image", "audio", or "all". Keep this narrow to avoid indexing large binary corpora unintentionally.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Memory Search Output Dimensionality`},help:{"v1-1f7zu53-93":`Provider-specific output vector size override for memory embeddings. Gemini models support 128-3072 dimensions and recommend 768, 1536, or 3072; Bedrock families such as Titan V2, Cohere V4, and Nova expose their own allowed sizes. Expect a full reindex when you change it because stored vector dimensions must stay consistent.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Memory Search Provider`},help:{"v1-5evseb-71":`Selects the embedding backend used to build/query memory vectors. Defaults to "openai"; set "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama", or "local" when you want a different backend.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Memory Search Max Results`},help:{"v1-13ekath-4x":`Maximum number of memory hits returned from search before downstream reranking and prompt injection. Raise for broader recall, or lower for tighter prompts and faster responses.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Memory Search Min Score`},help:{"v1-1ww231l-4v":`Minimum relevance score threshold for including memory results in final recall output. Increase to reduce weak/noisy matches, or lower when you need more permissive retrieval.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Memory Search Query Input Type`},help:{"v1-831yrv-4q":"Optional provider-specific `input_type` value for query-time memory embeddings. Use this with OpenAI-compatible asymmetric embedding endpoints that require a query label."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Remember Across Conversations`},help:{"v1-k1itm8-7y":`Use relevant context from this agent's other private conversations through protected transcript recall. Defaults on only when global session.dmScope is unset or "main" and no binding overrides DM scope; any configured DM isolation defaults it off. An explicit true or false always wins.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Remote Embedding API Key`},help:{"v1-nfuuu-62":`Supplies a dedicated API key for remote embedding calls used by memory indexing and query-time embeddings. Use this when memory embeddings should use different credentials than global defaults or environment variables.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Remote Embedding Base URL`},help:{"v1-1ugvqgt-5p":`Overrides the embedding API endpoint, such as an OpenAI-compatible proxy or custom Gemini base URL. Use this only when routing through your own gateway or vendor endpoint; keep provider defaults otherwise.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Remote Batch Embedding Enabled`},help:{"v1-1fehqi-5x":`Enables provider batch APIs for embedding jobs when supported (OpenAI/Gemini), improving throughput on larger index runs. Keep this enabled unless debugging provider batch failures or running very small workloads.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Remote Embedding Headers`},help:{"v1-1uic0kd-5i":`Adds custom HTTP headers to remote embedding requests, merged with provider defaults. Use this for proxy auth and tenant routing headers, and keep values minimal to avoid leaking sensitive metadata.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Memory Search Sources`},help:{"v1-btxtzg-57":`Chooses which sources are indexed: "memory" reads MEMORY.md + memory files, and "sessions" includes transcript history. Keep ["memory"] unless you need recall from prior chat transcripts.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Memory Search Vector Index`},help:{"v1-fbybkj-37":`Controls the sqlite-vec semantic index. Keep this advanced override when root and per-agent vector policies differ.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Memory Search Vector Extension Path`},help:{"v1-1hysv5q-58":"Overrides the auto-discovered sqlite-vec extension library path (`.dylib`, `.so`, or `.dll`). Use this when your runtime cannot find sqlite-vec automatically or you pin a known-good build."}},messages:{label:{"v1-1wwzqad-8":`Messages`},help:{"v1-i5k0iw-5k":`Message infrastructure and cross-agent defaults. Root siblings own infrastructure and cross-agent defaults; agents.defaults owns agent-loop behavior; agent entries may override either where supported.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Ack Reaction Emoji`},help:{"v1-1iip0zs-1x":`Emoji reaction used to acknowledge inbound messages (empty disables).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Ack Reaction Scope`},help:{"v1-1jvdg5n-7s":`When to send ack reactions ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" acks group messages that mention the agent, whether or not the group requires mentions; "group-all" acks every group message. "off"/"none" disables ack reactions entirely.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Group Chat Rules`},help:{"v1-chqsvh-4l":`Group-message handling controls including mention triggers and history window sizing. Keep mention patterns narrow so group channels do not trigger on every message.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Group History Limit`},help:{"v1-1mkbpw-9k":`Maximum number of prior group messages loaded as context per turn for group sessions. Use higher values for richer continuity, or lower values for faster and cheaper responses. Automatic prompt history is capped at 200 messages. The JSON integer maximum selects the channel default window (50 for shared group history), not an unlimited window.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Group Mention Patterns`},help:{"v1-i7h7qc-6f":`Safe case-insensitive regex patterns used to detect explicit mentions/trigger phrases in group chats. Use precise patterns to reduce false positives in high-volume channels; invalid or unsafe nested-repetition patterns are ignored.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Group Unmentioned Inbound`},help:{"v1-17wef8h-5f":`Controls how unmentioned always-on group chatter is submitted. "user_request" treats it as a user request; "room_event" submits it as quiet context where visible output requires the message tool.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Group Visible Replies`},help:{"v1-qa4z1s-aa":`Overrides model-authored source replies for group/channel conversations. Defaults to "automatic" when no global visible reply policy is set. "message_tool" requires message(action=send) for normal assistant output and generic tool media; explicitly host-owned runtime output remains deliverable except for ambient room events. "automatic" posts normal replies as before.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Inbound Debounce`},help:{"v1-ebyu5x-4a":`Direct inbound debounce settings used before queue/turn processing starts. Configure this for provider-specific rapid message bursts from the same sender.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Inbound Debounce by Channel (ms)`},help:{"v1-wbz54j-4g":`Per-channel inbound debounce overrides keyed by provider id in milliseconds. Use this where some providers send message fragments more aggressively than others.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Inbound Message Debounce (ms)`},help:{"v1-1616yo2-7w":`Quiet window (ms) for batching rapid inbound messages from the same sender. Telegram defaults to 300ms when neither a global nor channel override is set; other channels default to 0. Zero disables ordinary burst batching, but Telegram still reassembles near-limit long-message chunks.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Inbound Queue`},help:{"v1-hm2o31-48":`Queue strategy for inbound messages that arrive while a session run is active. Use this to tune steering, deferred followups, batching, or interruption.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Queue Mode by Channel`},help:{"v1-4rf8z8-54":`Per-channel queue mode overrides keyed by provider id (for example telegram, discord, slack). Use this when one channel's traffic pattern needs different behavior than global defaults.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Queue Capacity`},help:{"v1-16ql8c7-4j":`Maximum number of queued inbound items retained before drop policy applies. Default is 20; keep caps bounded in noisy channels so memory usage remains predictable.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Queue Fallback Debounce by Channel (ms)`},help:{"v1-4tpyt7-4e":`Per-channel debounce overrides for queue behavior keyed by provider id. Use this to tune burst handling independently for chat surfaces with different pacing.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Queue Drop Strategy`},help:{"v1-ydb2rw-6m":`Drop strategy when queue cap is exceeded. "summarize" drops oldest entries but preserves compact summaries; "old" drops oldest without summaries; "new" rejects the newest item. Use "summarize" for long-running chats where context matters.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Queue Mode`},help:{"v1-19k7gy1-67":`Queue mode for active runs. Use "steer" to inject prompts into the active run, "followup" to run later, "collect" to batch compatible messages later, or "interrupt" to abort the active run before starting the newest prompt.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Outbound Response Prefix`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Default Usage Footer Mode`},help:{"v1-l3shsx-dv":`Default per-reply usage footer mode ("off"|"tokens"|"full") seeded into sessions that have not chosen one via /usage. Also accepts "on" as a legacy alias for "tokens". Accepts a bare mode or a per-channel map with a "default" fallback. Precedence: session value -> channel entry -> default -> off; an explicit /usage choice (including off) is persisted and overrides the default. Use /usage reset (aliases: inherit, clear, default) to clear a session override and re-inherit this configured default.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Status Reactions`},help:{"v1-193764l-3s":`Lifecycle status reactions that update the emoji on the trigger message as the agent progresses (queued → thinking → tool → done/error).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Enable Status Reactions`},help:{"v1-1qnmmnc-7x":`Enable lifecycle status reactions on supported channels. Discord treats unset as enabled when ack reactions are active; Slack, Signal, Telegram, and WhatsApp require this to be true before lifecycle reactions are used. Slack uses native assistant thread status for progress by default.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Usage Footer Template`},help:{"v1-1xibc23-47":`Custom /usage full footer template, either an inline object or a JSON file path. Invalid or unavailable templates fall back to the built-in usage line.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Visible Replies`},help:{"v1-7yfwc2-8t":`Controls model-authored source replies across direct, group, and channel conversations. "message_tool" requires message(action=send) for normal assistant output and generic tool media; explicitly host-owned runtime output remains deliverable except for ambient room events. "automatic" posts normal replies as before.`}},meta:{label:{"v1-1xpfxac-m":`Compatibility Metadata`},help:{"v1-1owqhgn-2w":`Backward-readable compatibility metadata retained so older binaries can refuse unsafe config downgrades.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Config Last Touched Version`},help:{"v1-1hy3ucp-1i":`Assistant version that most recently wrote this config.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Config Migration Markers`},help:{"v1-burt8q-1q":`Bounded compatibility markers for completed config migrations.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Model Policy Allowlist Migration`},help:{"v1-5psop1-1z":`Records that legacy model-map restrictions were preserved or evaluated.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Utility Model Separation Migration`},help:{"v1-vzdfqx-2t":`Records that legacy implicit primary models were preserved before separating utility model selection.`}},models:{label:{"v1-hzmwb-6":`Models`},help:{"v1-1h1niol-5q":`Model catalog root for provider definitions, merge/replace behavior, and optional Bedrock discovery integration. Keep provider definitions explicit and validated before relying on production failover paths.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Model Catalog Refresh`},help:{"v1-1hess4t-40":`Controls background updates to the bundled model catalog. Remote rows can update model metadata but cannot change provider endpoints or headers.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Model Catalog Refresh Enabled`},help:{"v1-1fogpjj-3j":`Fetch hosted model catalog updates in the background (default: true). Set to false to disable all remote model catalog traffic.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`Model Catalog Refresh URL`},help:{"v1-e02ai2-44":`Override the hosted model catalog URL for a self-hosted HTTPS mirror (localhost HTTP is allowed for testing). Changes apply after a Gateway restart.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Model Catalog Mode`},help:{"v1-1ofrnsp-es":`Controls provider catalog behavior: "merge" keeps built-ins and overlays your custom providers, while "replace" uses only your configured providers. In "merge", matching provider IDs preserve non-empty agent models.json baseUrl values, while apiKey values are preserved only when the provider is not SecretRef-managed in current config/auth-profile context; SecretRef-managed providers refresh apiKey from current source markers, and matching model contextWindow/maxTokens use the higher value between explicit and implicit entries.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Model Providers`},help:{"v1-1y5jg0v-8p":`Provider map keyed by provider ID containing connection/auth settings and concrete model definitions. Built-in providers may be tuned with provider-level overlays; custom providers must include baseUrl and models. Use stable provider keys so references from agents and tooling remain portable across environments.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Model Provider Runtime`},help:{"v1-1hfw6cv-5o":`Optional low-level agent runtime policy for this provider. Use provider/model runtime policy instead of agent-wide runtime pins; omitted/default lets Assistant choose the runtime for the selected provider.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Model Provider Runtime ID`},help:{"v1-1kuni0o-69":`Provider agent runtime id: "testclaw", "auto", a registered plugin harness id such as "codex", or a supported CLI backend alias such as "claude-cli". OpenAI on the official endpoint defaults to the Codex harness when omitted.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Model Provider API Adapter`},help:{"v1-16c28rb-57":`Provider API adapter selection controlling request/response compatibility handling for model calls. Use the adapter that matches your upstream provider protocol to avoid feature mismatch.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Model Provider API Key`},help:{"v1-1p84k96-54":`Provider credential used for API-key based authentication when the provider requires direct key auth. Use secret/env substitution and avoid storing real keys in committed config files.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Model Provider Auth Mode`},help:{"v1-1l1lwxr-5p":`Selects provider auth style: "api-key" for API key auth, "token" for bearer token auth, "oauth" for OAuth credentials, and "aws-sdk" for AWS credential resolution. Match this to your provider requirements.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Model Provider Authorization Header`},help:{"v1-1gn3lt3-59":`When true, credentials are sent via the HTTP Authorization header even if alternate auth is possible. Use this only when your provider or proxy explicitly requires Authorization forwarding.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Model Provider Base URL`},help:{"v1-1ku88v8-53":`Base URL for the provider endpoint used to serve model requests for that provider entry. Use HTTPS endpoints and keep URLs environment-specific through config templating where needed.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Model Provider Headers`},help:{"v1-chg59u-4x":`Static HTTP headers merged into provider requests for tenant routing, proxy auth, or custom gateway requirements. Use this sparingly and keep sensitive header values in secrets.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Model Provider Inject num_ctx (OpenAI Compat)`},help:{"v1-8jdorn-6n":"Controls whether Assistant injects `options.num_ctx` for Ollama providers configured with the OpenAI-compatible adapter (`openai-completions`). Default is true. Set false only if your proxy/upstream rejects unknown `options` payload fields."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Model Provider Local Service`},help:{"v1-1wopabs-4y":`Optional on-demand local model server process for this provider. Assistant probes healthUrl, starts the command when needed, waits for readiness, and then sends the model request.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Model Provider Local Service Arguments`},help:{"v1-t12wib-27":`Argument list passed to the local model server command without shell expansion.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Model Provider Local Service Command`},help:{"v1-1x6hz64-4j":`Absolute executable path for the local model server process. Keep this path explicit so provider startup is deterministic and does not depend on shell PATH lookup.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Model Provider Local Service Working Directory`},help:{"v1-fi3xlx-1h":`Working directory for the local model server process.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Model Provider Local Service Environment`},help:{"v1-1lwb9k1-3k":`Additional environment variables for the local model server process. Values that look secret are redacted from config snapshots.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`Model Provider Local Service Health URL`},help:{"v1-5rzc1s-35":`Readiness URL probed before model requests. If omitted, Assistant uses the provider baseUrl with /models appended.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Model Provider Local Service Idle Stop`},help:{"v1-1e0svuw-3z":`Milliseconds to keep an Assistant-started local model server alive after the last request finishes. Set 0 to keep it alive until Assistant exits.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Model Provider Local Service Ready Timeout`},help:{"v1-4gp0f0-2r":`Maximum milliseconds to wait for the local model server readiness probe after starting the process.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Model Provider Max Tokens`},help:{"v1-fnj50y-38":`Default maximum output token budget applied to models under this provider when a model entry does not set maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Model Provider Model List`},help:{"v1-1vbm0gt-63":`Declared model list for a provider including identifiers, metadata, provider-specific params, and optional compatibility/cost hints. Keep IDs exact to provider catalog values so selection and fallback resolve correctly.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Model Runtime`},help:{"v1-1k70g2n-3g":`Optional low-level agent runtime policy for this specific model. Model runtime policy overrides the provider runtime policy.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Model Runtime ID`},help:{"v1-hzltsj-42":`Model agent runtime id: "testclaw", "auto", a registered plugin harness id such as "codex", or a supported CLI backend alias such as "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Model Media Input`},help:{"v1-wxtj8e-2x":`Optional model media capability metadata used by tools to choose conservative image compression defaults.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Model Image Input`},help:{"v1-1nviirq-3c":`Optional image input limits for this model, such as maximum side length, maximum pixels, and preferred compression side.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Model Image Max Bytes`},help:{"v1-c2469j-23":`Maximum encoded image payload size accepted by the provider for this model.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Model Image Max Pixels`},help:{"v1-9d6yqp-1u":`Maximum image pixel count accepted by the provider for this model.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Model Image Max Side`},help:{"v1-1gbci08-1y":`Maximum image width or height accepted by the provider for this model.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Model Image Preferred Side`},help:{"v1-jw849k-2x":`Preferred image resize side for balanced compression. Leave unset to use Assistant's conservative default.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Model Image Token Mode`},help:{"v1-1oy6z7v-1z":`Provider image token accounting style: "tile", "detail", or "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Model Provider Runtime Parameters`},help:{"v1-464sgu-4t":`Provider-specific runtime parameters interpreted by provider plugins. Keep keys documented by the provider, and prefer explicit provider docs over ad hoc shared assumptions.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Model Provider Region`},help:{"v1-yq7rxk-5h":`Optional provider deployment/API region interpreted by providers that expose regional endpoints. Use provider docs for supported values; baseUrl overrides usually take precedence when both are set.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Model Provider Request Overrides`},help:{"v1-1lkxryk-87":`Optional request overrides for model-provider requests, including extra headers, auth overrides, proxy routing, TLS client settings, and optional allowPrivateNetwork for trusted self-hosted endpoints. Use these only when your upstream or enterprise network path requires transport customization.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Model Provider Request Allow Private Network`},help:{"v1-1nbtcjk-fo":`When true, allow model-provider HTTP requests to private, CGNAT, or similar ranges through the provider HTTP fetch guard (fetchWithSsrFGuard). Custom/local provider base URLs already trust the exact configured origin, except metadata, link-local, and local-use NAT64 (64:ff9b:1::/48) origins; set this to false to opt out of that trust. OpenAI Responses WebSocket reuses request for headers/TLS but does not use that fetch SSRF path. Use true only for operator-controlled self-hosted endpoints that must reach private origins outside the configured baseUrl origin.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Model Provider Request Auth Override`},help:{"v1-ucdgnf-1w":`Override provider request authentication behavior for this provider.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Model Provider Request Auth Header Name`},help:{"v1-1881nqr-1i":`Custom auth header name used when auth mode is header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Model Provider Request Auth Mode`},help:{"v1-1lhv8hs-24":`Auth override mode: "provider-default", "authorization-bearer", or "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Model Provider Request Auth Header Prefix`},help:{"v1-1rbm9lz-21":`Optional prefix prepended to request.auth.value when auth mode is header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Model Provider Request Bearer Token`},help:{"v1-6rcasw-1l":`Bearer token used when auth mode is authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Model Provider Request Auth Header Value`},help:{"v1-1v69ej-1j":`Custom auth header value used when auth mode is header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Model Provider Request Headers`},help:{"v1-zj3orj-2i":`Extra headers merged into provider requests after default attribution and auth resolution.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Model Provider Request Proxy`},help:{"v1-md5uj8-4j":`Optional proxy override for model-provider requests. Use "env-proxy" to honor environment proxy settings or "explicit-proxy" to route through a specific proxy URL.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Model Provider Request Proxy Mode`},help:{"v1-1dx0ozg-29":`Proxy override mode for model-provider requests: "env-proxy" or "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`Model Provider Request Proxy TLS`},help:{"v1-rdx62w-1v":`Optional TLS settings used when connecting to the configured proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`Model Provider Request Proxy TLS CA`},help:{"v1-11pg2fd-1s":`Custom CA bundle used to verify the proxy TLS certificate chain.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Model Provider Request Proxy TLS Cert`},help:{"v1-x8nk2q-22":`Client TLS certificate presented to the proxy when mutual TLS is required.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Model Provider Request Proxy TLS Skip Verify`},help:{"v1-12vjdm9-2j":`Skips proxy TLS certificate verification. Use only for controlled development environments.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Model Provider Request Proxy TLS Key`},help:{"v1-1skyr56-1w":`Private key paired with request.proxy.tls.cert for proxy mutual TLS.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Model Provider Request Proxy TLS Passphrase`},help:{"v1-wjvoxd-1m":`Optional passphrase used to decrypt request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Model Provider Request Proxy TLS Server Name`},help:{"v1-b4oabu-22":`Optional SNI/server-name override used when establishing TLS to the proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Model Provider Request Proxy URL`},help:{"v1-kvbgou-48":`Explicit proxy URL used when request.proxy.mode is explicit-proxy. Credentials embedded in the URL are treated as sensitive and redacted from snapshots.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`Model Provider Request TLS`},help:{"v1-16u7v7h-2b":`Optional TLS settings used when connecting directly to the upstream model endpoint.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`Model Provider Request TLS CA`},help:{"v1-ny8y3e-1v":`Custom CA bundle used to verify the upstream TLS certificate chain.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Model Provider Request TLS Cert`},help:{"v1-1lltmhw-2e":`Client TLS certificate presented to the upstream endpoint when mutual TLS is required.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Model Provider Request TLS Skip Verify`},help:{"v1-1006cuy-2m":`Skips upstream TLS certificate verification. Use only for controlled development environments.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Model Provider Request TLS Key`},help:{"v1-w2agir-1t":`Private key paired with request.tls.cert for upstream mutual TLS.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Model Provider Request TLS Passphrase`},help:{"v1-10ds42f-1g":`Optional passphrase used to decrypt request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Model Provider Request TLS Server Name`},help:{"v1-18yt7x9-1y":`Optional SNI/server-name override used when establishing upstream TLS.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Model Provider Request Timeout`},help:{"v1-t3yn8l-ih":`Optional per-provider model request timeout in seconds. Provider-level request settings affect explicit provider-owned model rows; they do not create implicit models. For custom providers, set it alongside the provider baseUrl and models. Applies to provider HTTP fetches, including connect, headers, body, and total request abort handling, and also raises the LLM idle/stream watchdog ceiling for this provider above the implicit ~120s default. Use this for slow local or self-hosted model servers, or for cloud providers that buffer reasoning tokens silently on the wire (Gemini preview, large-tool-payload Claude/Opus), instead of changing global agent timeouts.`}},nodeHost:{label:{"v1-nb8lk1-9":`Node Host`},help:{"v1-8recuz-4z":`Node host controls for features exposed from this gateway node to other nodes or clients. Keep defaults unless you intentionally proxy local capabilities across your node network.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Node Agent Runs`},help:{"v1-4uz5ur-2k":`Opt in to approval-gated native agent turns on this headless node host. Disabled by default.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Node Claude Agent Runs`},help:{"v1-g8az5y-2l":`Controls whether this headless node host may advertise Claude CLI agent turns to the gateway.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Node Claude Agent Runs Enabled`},help:{"v1-1ke804l-44":`Advertise paired-node Claude session continuation when the local claude binary is available (default: false). Runs still require node exec approval.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Node Automatic Updates`},help:{"v1-16xjk4e-5n":`Controls automatic updates of the separate runtime for packaged headless node hosts. Checks hourly and waits for all node work to finish before restarting; automatic restarts are at least 12 hours apart.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Node Automatic Updates Enabled`},help:{"v1-1mckjkc-7w":`Enable automatic stable or beta updates for long-running packaged headless nodes (default: true). Set false to opt out. Also disabled by update.checkOnStart=false or TESTCLAW_NO_AUTO_UPDATE=1; source checkouts, native apps, private workers, dev, and extended-stable do not auto-apply.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Node Browser Proxy`},help:{"v1-2xrew7-4f":`Groups browser-proxy settings for exposing local browser control through node routing. Enable only when remote node workflows need your local browser profiles.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Node Browser Proxy Allowed Profiles`},help:{"v1-132wiiy-8b":`Optional allowlist of browser profile names exposed through node proxy routing. Leave empty to preserve the default full profile surface, including profile create/delete routes. When set, Assistant enforces least-privilege profile access and blocks persistent profile create/delete through the proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Node Browser Proxy Enabled`},help:{"v1-pa04pd-5b":`Expose the local browser control server through node proxy routing so remote clients can use this host's browser capabilities. Keep disabled unless remote automation explicitly depends on it.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`Node Host MCP`},help:{"v1-1mdhrwl-48":`Use MCP servers started by the headless node host and published to its paired gateway as agent tools. Restart the node host after changing this section.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Node Host MCP Servers`},help:{"v1-19m002f-3x":`Named MCP server definitions local to this node. Uses the same server shape as mcp.servers; OAuth servers are not supported by the node host.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Node Host Skills`},help:{"v1-16868su-41":`Use this section to publish skills installed in ~/.testclaw/skills from the headless node host. Restart the node host after changing skill files.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Node Host Skills Enabled`},help:{"v1-1ggpkqb-36":`Scan and publish node-hosted skills after connecting (default: true). Set false to disable node skill publication.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Node Worker Runs`},help:{"v1-ilx10d-2p":`Opt in to full Assistant worker session hosting from Gateway-managed bundles. Disabled by default.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Node Worker Run Capacity`},help:{"v1-10nvk8f-3w":`Maximum concurrent worker sessions hosted by this node (default: the number of available CPU cores). Must be an integer from 1 through 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Node Worker Run Container Image`},help:{"v1-1oqx50o-5t":`Optional Node 24.16+ or 26.1+ image for container-isolated workers (default: "node:24.19.0-slim"). Use a digest-pinned, private-registry, or preloaded image when needed; missing images are pulled on first use.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Node Worker Runs Enabled`},help:{"v1-b3t0xp-2t":`Allow this paired node to host sessions from exact bundles installed by its Gateway (default: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Node Worker Run Isolation`},help:{"v1-19i6swo-58":`Select the worker-session process boundary: "none" runs directly on the node host (default); "container" requires a working Docker-compatible engine and never falls back to host execution.`}},plugins:{label:{"v1-10renyj-7":`Plugins`},help:{"v1-1qbev2k-5c":`Plugin system controls for enabling extensions, constraining load scope, configuring entries, and tracking installs. Keep plugin policy explicit and least-privilege in production environments.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Plugin Allowlist`},help:{"v1-pupwbe-7z":`Optional allowlist of plugin IDs; when set, only listed plugins are eligible to load. Configured bundled chat channels can still activate their bundled plugin when the channel is explicitly enabled in config. Use this to enforce approved extension inventories in controlled environments.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Plugin Denylist`},help:{"v1-4gyt4z-4i":`Optional denylist of plugin IDs that are blocked even if allowlists or paths include them. Use deny rules for emergency rollback and hard blocks on risky plugins.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Enable Plugins`},help:{"v1-pnygd7-50":`Enable or disable plugin/extension loading globally during startup and config reload (default: true). Keep enabled only when extension capabilities are required by your deployment.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Plugin Entries`},help:{"v1-cn74rf-54":`Per-plugin settings keyed by plugin ID including enablement and plugin-specific runtime configuration payloads. Use this for scoped plugin tuning without changing global loader policy.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Plugin API Key`},help:{"v1-ctytg2-53":`Optional API key field consumed by plugins that accept direct key configuration in entry settings. Use secret/env substitution and avoid committing real credentials into config files.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Plugin Config`},help:{"v1-1he672p-51":`Plugin-defined configuration payload interpreted by that plugin's own schema and validation rules. Use only documented fields from the plugin to prevent ignored or invalid settings.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin Enabled`},help:{"v1-12soc0h-9a":`Per-plugin enablement override for a specific entry, applied on top of global plugin policy. With the default hybrid reload mode, changes hot-reload the plugin runtime for new agent turns without restarting the Gateway unless the plugin requires a restart for this path. Use this to stage plugin rollout gradually across environments.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Plugin Environment Variables`},help:{"v1-p39pu4-52":`Per-plugin environment variable map injected for that plugin runtime context only. Use this to scope provider credentials to one plugin instead of sharing global process environment.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Plugin Hook Policy`},help:{"v1-1oslnrf-4c":`Per-plugin typed hook policy controls for core-enforced safety gates. Use this to constrain high-impact hook categories without disabling the entire plugin.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Allow Conversation Access Hooks`},help:{"v1-xqz31z-7e":"Controls whether this plugin may read raw conversation content from typed hooks such as `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize`, and `agent_end`. Non-bundled plugins must opt in explicitly."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Allow Prompt Injection Hooks`},help:{"v1-7y6cny-32":"Controls whether this plugin may mutate prompts through typed hooks. Set false to block `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Plugin Hook Timeout (ms)`},help:{"v1-4ra6b7-74":`Default timeout in milliseconds for this plugin's typed hooks, capped at 600000. When unset, each hook uses the plugin's declared timeout or the Gateway's per-hook policy; there is no single fixed default. Per-hook values in hooks.timeouts take precedence.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Plugin Hook Timeout Overrides`},help:{"v1-yphl9b-5s":`Per-hook timeout overrides in milliseconds keyed by typed hook name, capped at 600000. Use narrow overrides for known slow hooks such as before_prompt_build or agent_end instead of raising every hook timeout.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Plugin LLM Policy`},help:{"v1-dlca6c-4j":`Per-plugin api.runtime.llm.complete controls for model and agent override trust. Keep this unset unless a plugin must explicitly steer host-owned completion calls.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Allow Plugin LLM Agent Override`},help:{"v1-k8c08b-4n":`Explicitly allows this plugin to request api.runtime.llm.complete against a non-default agent id. Keep false unless the plugin is trusted for cross-agent model access.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Allow Plugin LLM Auth Profile Override`},help:{"v1-9ityw9-4x":`Allows this plugin to select a non-default auth profile for isolated agent-runtime completions. Keep false unless the plugin is trusted for explicit isolated credential routing.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Plugin LLM Allowed Completion Models`},help:{"v1-1ul08he-54":`Allowed targets for every plugin LLM completion as canonical "provider/model" refs, including host-resolved defaults and overrides. Use "*" only when you intentionally allow any model.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Plugin LLM Allowed Models`},help:{"v1-154sk45-47":`Allowed override targets for trusted plugin LLM calls as canonical "provider/model" refs. Use "*" only when you intentionally allow any model override.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Allow Plugin LLM Model Override`},help:{"v1-uw4jmc-47":`Explicitly allows this plugin to request model overrides in api.runtime.llm.complete. Keep false unless the plugin is trusted to steer model selection.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Plugin Subagent Policy`},help:{"v1-wbf4m1-4d":`Per-plugin subagent runtime controls for model override trust and allowlists. Keep this unset unless a plugin must explicitly steer subagent model selection.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Plugin Subagent Allowed Models`},help:{"v1-2pvkow-42":`Allowed override targets for trusted plugin subagent runs as canonical "provider/model" refs. Use "*" only when you intentionally allow any model.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Allow Plugin Subagent Model Override`},help:{"v1-1r5tzm1-4g":`Explicitly allows this plugin to request provider/model overrides in background subagent runs. Keep false unless the plugin is trusted to steer model selection.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Plugin Loader`},help:{"v1-1myjwbi-52":`Plugin loader configuration group for specifying filesystem paths where plugins are discovered. Keep load paths explicit and reviewed to avoid accidental untrusted extension loading.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Plugin Load Paths`},help:{"v1-o689p1-4z":`Additional plugin files or directories scanned by the loader beyond built-in defaults. Use dedicated extension directories and avoid broad paths with unrelated executable content.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Plugin Slots`},help:{"v1-zx6crl-5f":`Selects which plugins own exclusive runtime slots such as memory so only one plugin provides that capability. Use explicit slot ownership to avoid overlapping providers with conflicting behavior.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Context Engine Plugin`},help:{"v1-4v13iw-2t":`Selects the active context engine plugin by id so one plugin provides context orchestration behavior.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Memory Plugin`},help:{"v1-80ngcl-23":`Select the active memory plugin by id, or "none" to disable memory plugins.`}},presence:{label:{"v1-10fdwo4-8":`Presence`}},proxy:{label:{"v1-ji57pa-d":`Managed Proxy`},help:{"v1-frq3wl-58":`Operator-managed forward proxy routing for Runtime HTTP, HTTPS, WebSocket, and supported raw-egress paths. Use this when central egress control is part of the deployment boundary.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Managed Proxy Enabled`},help:{"v1-1456xdw-49":`Explicit managed-proxy override. URL presence enables routing by default; set false to ignore configured or environment proxy URLs without deleting them.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Managed Proxy Loopback Mode`},help:{"v1-1kaiuh0-3c":`Controls Gateway loopback control-plane routing while managed proxy mode is active: "gateway-only", "proxy", or "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`Managed Proxy URL`},help:{"v1-p36b5l-3v":`Managed forward proxy URL. Use http:// for a plain CONNECT proxy or https:// when the connection to the proxy endpoint itself must use TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`Managed Proxy TLS`},help:{"v1-6i0vu-3q":`TLS settings used when connecting to the managed proxy endpoint. These settings apply to proxy TLS, not destination TLS after CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Managed Proxy TLS CA File`},help:{"v1-1ntzjia-2p":`Filesystem path to a custom CA bundle used to verify an HTTPS managed proxy endpoint certificate.`}},secrets:{label:{"v1-1sihgpy-7":`Secrets`},help:{"v1-jgn0o9-2l":`Secret reference providers, shared-store behavior, and optional subprocess egress protection.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Secret Egress Proxy`},help:{"v1-1qfgid-4n":`Gateway-owned loopback proxy that replaces shared-store secret sentinels only at outbound request time. Restart the Gateway after changing this startup-scoped section.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Secret Egress Proxy Allowed Hosts`},help:{"v1-9ypodl-6t":`Opt-in traffic allowlist for requests and CONNECT tunnels. When present, destinations must appear in this list, a per-secret host binding, or bypassHosts. An empty list permits only bound or bypassed hosts. Restart the Gateway after changing it.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Secret Egress Proxy Bypass Hosts`},help:{"v1-1oiiomv-57":`Exact hostnames that use authenticated blind CONNECT tunnels for certificate-pinned clients. Sentinels remain ciphertext and will fail vendor authentication instead of exposing plaintext.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Secret Egress Proxy Enabled`},help:{"v1-u99b1i-2h":`Enables secret egress substitution for Gateway-hosted agent subprocesses. Default: false.`}},session:{label:{"v1-8yh9jr-7":`Session`},help:{"v1-j86s32-5d":`Global session routing, reset, delivery policy, and maintenance controls for conversation history behavior. Keep defaults unless you need stricter isolation, retention, or delivery constraints.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`DM Session Scope`},help:{"v1-ql362c-5l":`DM session scoping: "main" keeps continuity, while "per-peer", "per-channel-peer", and "per-account-channel-peer" increase isolation. Use isolated modes for shared inboxes or multi-account deployments.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Group Session Scope`},help:{"v1-1fdezx2-6i":`Group/channel session scoping: "per-group" keeps rooms separate while the agent main session ambiently watches them, independently of dmScope; "main" merges room context into main and needs no watch. Use "main" only for trusted rooms.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Session Identity Links`},help:{"v1-1y5jnsm-5n":`Maps canonical identities to provider-prefixed peer IDs so equivalent users resolve to one DM thread (example: telegram:123456). Use this when the same human appears across multiple channels or accounts.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Session Main Key`},help:{"v1-18p638h-3q":`Accepted but ignored: the per-agent main session suffix is always "main". Omit this field; global session scope uses "global" instead.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Session Maintenance`},help:{"v1-imr441-66":`Automatic session-store maintenance controls for dashboard archiving, pruning age, entry caps, reset archive retention, and disk budget cleanup. Start in warn mode to observe impact, then enforce once thresholds are tuned.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Archive Inactive Dashboard Sessions After`},help:{"v1-1frdtub-5n":"Archives inactive dashboard sessions after this duration (for example `7d`) so they remain available without crowding the active session list. Set `false` or `0` to disable automatic dashboard archiving."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Transcript Cold Storage`},help:{"v1-1kp9s9h-5s":`Moves inactive transcripts into compressed JSONL archives while retaining session metadata. Archive files become required history and must be included in backups. Changes apply without restarting the Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Archive After Inactive Days`},help:{"v1-zay1q3-5b":`Archive transcripts after this many inactive days (positive integer, default 30). Active work is protected; changing the cutoff takes effect on the next worker pass without a Gateway restart.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Automatically Archive Old Transcripts`},help:{"v1-6p6vmb-5a":`Enables background transcript archival (default false). A worker checks for eligible transcripts every minute. This explicit archive policy is separate from deletion and disk-budget cleanup.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Session Disk High-water Target`},help:{"v1-143vh09-7z":`Target size after disk-budget cleanup (high-water mark). Defaults to 80% of maxDiskBytes; set explicitly for tighter reclaim behavior on constrained disks. A value that resolves to zero falls back to the default; negative values are invalid. Disable the budget with maxDiskBytes instead.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Session Max Disk Budget`},help:{"v1-147lxk3-cj":'Per-agent physical disk budget covering SQLite main/WAL and counted session-directory artifacts (for example `500mb`). Defaults to `10gb`; protected data can keep usage above the target. When exceeded, warn mode reports pressure and enforce mode removes old reset/delete artifacts, unreferenced history, then cap-created archives. Manual, age-retention, dashboard, recovery, and legacy archives remain protected. Set `false`, `0`, or `"0"` to disable.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Session Max Entries`},help:{"v1-1w2egrh-7u":`Caps unarchived session entries (default 5000). Eligible durable overflow conversations are archived with their history; disposable automation entries are removed. Existing archives do not consume the cap. Protected active entries still count and can keep the store above the limit.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Session Maintenance Mode`},help:{"v1-bq39hk-6v":`Determines whether pruning and disk-budget policies are only reported ("warn") or actively applied ("enforce"). Keep "warn" during rollout and switch to "enforce" after validating safe thresholds. Cold storage has its own explicit enabled setting.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Preserve Recent Sessions`},help:{"v1-138q5wx-89":"Protects interactive sessions active within this duration (for example `7d`) from automatic age, count, and disk-budget history eviction. Unset or `false` keeps the normal oldest-first policy. Synthetic model-run, cron, hook, heartbeat, ACP, and sub-agent rows remain eligible for bounded cleanup."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Session Prune After`},help:{"v1-1xn50w7-76":"Archives eligible durable conversations and removes disposable automation entries older than this duration (default `30d`; for example `12h`). Archived conversations retain their history and can be restored; protected or routable conversations remain active."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Session Reset Archive Retention`},help:{"v1-16amrs1-7r":"Age-based retention for archived transcripts (`*.reset.<timestamp>` and `*.deleted.<timestamp>`). Defaults to keeping archives until the disk budget evicts them oldest-first; set a duration (for example `30d`) to opt into wall-clock deletion, or `false` to disable it explicitly."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Notify Home on Session Creation`},help:{"v1-c4prn5-8b":`Queue a system notice in the owning agent's Home session when a session is created (default: true). Notices include available title and creator metadata and are read on the next Home turn or heartbeat. Set false to disable; drafts, incognito, internal sessions, and scheduled cron runs are excluded.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Session Reset Policy`},help:{"v1-1hmt7n3-6r":`Defines the default reset policy object used when no type-specific or channel-specific override applies. By default sessions do not reset automatically; use daily or idle schedules to opt in, while /new and /reset remain available at any time.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Session Daily Reset Hour`},help:{"v1-wry8cv-59":`Sets local-hour boundary (0-23) for daily reset mode so sessions roll over at predictable times. Use with mode=daily and align to operator timezone expectations for human-readable behavior.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Session Reset Idle Minutes`},help:{"v1-1kzj0id-5e":`Sets inactivity window before reset for idle mode and can also act as secondary guard with daily mode. Use larger values to preserve continuity or smaller values for fresher short-lived threads.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Session Reset Mode`},help:{"v1-e5ie4w-5b":`Selects reset strategy: "none" disables automatic reset (the default), "daily" resets at a configured hour, and "idle" resets after inactivity. /new and /reset remain available in every mode.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Session Reset by Channel`},help:{"v1-1uxsulx-5h":`Provides channel-specific reset overrides keyed by provider/channel id for fine-grained behavior control. Use this only when one channel needs exceptional reset behavior beyond type-level policies.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Session Reset by Chat Type`},help:{"v1-ypdr7u-52":`Overrides reset behavior by chat type (direct, group, thread) when defaults are not sufficient. Use this when group/thread traffic needs different reset cadence than direct messages.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Session Reset (Direct)`},help:{"v1-fjnlp5-56":`Defines reset policy for direct chats and supersedes the base session.reset configuration for that type. Use this as the canonical direct-message override instead of the legacy dm alias.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Session Reset (Group)`},help:{"v1-hl1200-4u":`Defines reset policy for group chat sessions where continuity and noise patterns differ from DMs. Use shorter idle windows for busy groups if context drift becomes a problem.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Session Reset (Thread)`},help:{"v1-1hgpeke-4w":`Defines reset policy for thread-scoped sessions, including focused channel thread workflows. Use this when thread sessions should expire faster or slower than other chat types.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Session Reset Triggers`},help:{"v1-rcabsw-5a":`Lists message triggers that force a session reset when matched in inbound content. Use sparingly for explicit reset phrases so context is not dropped unexpectedly during normal conversation.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Session Scope`},help:{"v1-axt4ds-5z":`Sets base session grouping strategy: "per-sender" isolates by sender and "global" shares one session per channel context. Keep "per-sender" for safer multi-user behavior unless deliberate shared context is required.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Session Send Policy`},help:{"v1-17qpipb-5l":`Controls cross-session send permissions using allow/deny rules evaluated against channel, chatType, and key prefixes. Use this to fence where session tools can deliver messages in complex environments.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Session Send Policy Default Action`},help:{"v1-15plhut-53":`Sets fallback action when no sendPolicy rule matches: "allow" or "deny". Keep "allow" for simpler setups, or choose "deny" when you require explicit allow rules for every destination.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Session Send Policy Rules`},help:{"v1-o217za-5h":'Ordered allow/deny rules evaluated before the default action, for example `{ action: "deny", match: { channel: "discord" } }`. Put most specific rules first so broad rules do not shadow exceptions.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Session Send Rule Action`},help:{"v1-178vm80-54":`Defines rule decision as "allow" or "deny" when the corresponding match criteria are satisfied. Use deny-first ordering when enforcing strict boundaries with explicit allow exceptions.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Session Send Rule Match`},help:{"v1-18qh5qg-5d":`Defines optional rule match conditions that can combine channel, chatType, and key-prefix constraints. Keep matches narrow so policy intent stays readable and debugging remains straightforward.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Session Send Rule Channel`},help:{"v1-u5erwx-50":`Matches rule application to a specific channel/provider id (for example discord, telegram, slack). Use this when one channel should permit or deny delivery independently of others.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Session Send Rule Chat Type`},help:{"v1-7cv4f9-4z":`Matches rule application to chat type (direct, group, thread) so behavior varies by conversation form. Use this when DM and group destinations require different safety boundaries.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Session Send Rule Key Prefix`},help:{"v1-ac4dee-5n":`Matches a normalized session-key prefix after internal key normalization steps in policy consumers. Use this for general prefix controls, and prefer rawKeyPrefix when exact full-key matching is required.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Session Send Rule Raw Key Prefix`},help:{"v1-1g9w044-5e":`Matches the raw, unnormalized session-key prefix for exact full-key policy targeting. Use this when normalized keyPrefix is too broad and you need agent-prefixed or transport-specific precision.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Session Sharing Modes`},help:{"v1-xbh52d-5a":`Controls which collaboration modes session owners and administrators may select. Omitted booleans default to enabled; set a mode false to remove it from the picker and reject new selections.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Allow Draft Sessions`},help:{"v1-1lzap27-2p":`Allows draft visibility, which hides sessions from non-owner, non-admin operators. Default: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Allow Read-only Sessions`},help:{"v1-upl3nu-21":`Allows sessions to be made read-only for non-participants. Default: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Allow Suggest Sessions`},help:{"v1-4i8owu-4g":`Allows suggest visibility. In this phase it enforces the same admission policy as read-only; suggestion queues are configured by a later feature. Default: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Session Store Path`},help:{"v1-hreznz-56":`Sets the session storage file path used to persist session records across restarts. Use an explicit path only when you need custom disk layout, backup routing, or mounted-volume storage.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Session Thread Bindings`},help:{"v1-zbzihu-4s":`Shared defaults for thread-bound session spawning and routing across supported channels. Configure global defaults here and override per channel only when behavior differs.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Thread Spawn Context`},help:{"v1-1set6nw-4c":`Default native subagent context for thread-bound spawns. Use "fork" to start from the requester transcript or "isolated" for a clean child. Default: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Thread Binding Enabled`},help:{"v1-foomtc-3f":`Global master switch for thread-bound session spawning, routing, and delivery. Disable to turn off thread binding globally.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Thread Binding Idle Timeout (hours)`},help:{"v1-gffnx3-3h":`Default inactivity window in hours for thread-bound sessions across providers/channels (0 disables idle expiry). Default: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Thread Binding Max Age (hours)`},help:{"v1-1xfcyhw-39":`Optional hard max age in hours for thread-bound sessions across providers/channels (0 disables hard cap). Default: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Thread-Bound Session Spawns`},help:{"v1-1lqwbdl-46":`Global default gate for creating thread-bound work sessions from sessions_spawn and ACP thread spawns. Default: true when thread bindings are enabled.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Allowed Skill Symlink Targets`},help:{"v1-xzybiq-4t":`Trusted real target roots that skill symlinks may resolve into when they sit outside their configured source root. Keep this narrow, such as a sibling repo skills directory.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Extra Skill Directories`},help:{"v1-2wjuzu-53":`Additional shared skill roots to scan at lowest precedence. Use this for sibling repos or shared skill packs that should be available without copying them into the Assistant workspace.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Watch Skills`},help:{"v1-1ckr2l5-5d":`Enable filesystem watching for skill-definition changes so updates can be applied without full process restart. Keep enabled in development workflows and disable in immutable production images.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Skill Workshop Autonomous Mode`},help:{"v1-1s3kgit-6j":`Controls background learning: "off" keeps only the suggestion nudge, "propose" creates pending proposals, and "auto" applies captured proposals and runs weekly review of Workshop-owned skills using ordinary file edits. Default: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Surface Policies`},help:{"v1-vgtjbs-50":`Per-surface message policy overrides keyed by the resolved delivery surface id. Use this only when one deployed surface needs stricter silent-reply handling than the agent default.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Surface Silent Reply Policy`},help:{"v1-12zgc3n-60":`Overrides silent-reply policy for one resolved delivery surface. Unset fields inherit agents.defaults.silentReply; use narrow surface ids so internal or group-specific behavior does not spill into other destinations.`}},talk:{label:{"v1-15ukbjj-4":`Talk`},help:{"v1-1gx10xa-5g":`Talk-mode voice synthesis settings for voice identity, model selection, output format, and interruption behavior. Use this section to tune human-facing voice UX while controlling latency and cost.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talk Agent`},help:{"v1-iee5l9-2b":`Agent that owns Talk sessions created without an explicit agent-scoped session key.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Talk Consult Fast Mode`},help:{"v1-syf3xk-2o":`Use this to set true or false fast mode for the regular agent run behind Talk realtime consults.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Talk Consult Thinking Level`},help:{"v1-1ft5njw-2o":`Use this to override the thinking level for the regular agent run behind Talk realtime consults.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Talk Interrupt on Speech`},help:{"v1-8n9q4o-3l":`If true (default), stop assistant speech when the user starts speaking in Talk mode. Keep enabled for conversational turn-taking.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Talk Active Provider`},help:{"v1-wgnxhg-1g":`Active Talk provider id (for example "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Talk Provider Settings`},help:{"v1-oh0yuv-30":`Provider-specific Talk settings keyed by provider id. During migration, prefer this over legacy talk.* keys.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Talk Provider Config`},help:{"v1-36pblg-1r":`Provider-owned Talk config fields for the matching provider id.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Talk Provider API Key`},help:{"v1-1a1p9wp-v":`Provider API key for Talk mode.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk Realtime`},help:{"v1-c2re7j-3z":`Realtime Talk provider, model, voice, mode, transport, and brain strategy. Keep speech/TTS provider config in talk.provider and talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Talk Realtime Brain`},help:{"v1-opsatw-37":`Talk reasoning strategy: agent-consult for Gateway-mediated agent help, direct-tools for local tool calls, or none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Talk Realtime Consult Routing`},help:{"v1-1r8g680-5f":`Gateway relay fallback for final user transcripts when the realtime provider skips testclaw_agent_consult. provider-direct preserves provider replies; force-agent-consult routes through Assistant.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Talk Realtime Instructions`},help:{"v1-plfzqw-5p":`Additional system instructions appended to Assistant's built-in realtime Talk prompt. Use this for voice style, tone, and other provider-facing realtime behavior while keeping agent-consult guidance intact.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Talk Realtime Mode`},help:{"v1-1u2xui1-1l":`Talk execution mode: realtime, stt-tts, or transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Talk Realtime Model`},help:{"v1-amou5a-27":`Realtime provider model id override for browser or Gateway-owned Talk sessions.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Talk Realtime Prefix Padding (ms)`},help:{"v1-1cwg07n-22":`Milliseconds of audio retained before realtime voice activity is detected.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Talk Realtime Provider`},help:{"v1-wwsmpt-1o":`Active realtime voice provider id, such as openai or google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Talk Realtime Provider Settings`},help:{"v1-ruagcu-1r":`Provider-specific realtime voice settings keyed by provider id.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Talk Realtime Provider Config`},help:{"v1-edfpxm-1u":`Provider-owned realtime voice config for the matching provider id.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Talk Realtime Provider API Key`},help:{"v1-1fbmgpx-z":`Provider API key for realtime Talk.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Talk Realtime Reasoning Effort`},help:{"v1-157xd3e-2t":`Provider-specific reasoning effort for realtime Talk sessions, such as minimal, low, medium, or high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Talk Realtime Silence Duration (ms)`},help:{"v1-1grnu06-1y":`Milliseconds of silence before a realtime Talk user turn is committed.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talk Realtime Speaker Voice`},help:{"v1-1kgb166-2h":`Realtime provider speaker voice name override for browser or Gateway-owned Talk sessions.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talk Realtime Speaker Voice ID`},help:{"v1-1k8w6vk-2f":`Realtime provider speaker voice id override for browser or Gateway-owned Talk sessions.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Talk Realtime Transport`},help:{"v1-2otjgn-2g":`Talk byte/session transport: webrtc, provider-websocket, gateway-relay, or managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Talk Realtime VAD Threshold`},help:{"v1-nf5l2t-2j":`Realtime voice activity detection threshold from 0 (most sensitive) to 1 (least sensitive).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Talk Silence Timeout (ms)`},help:{"v1-1kim32f-59":`Milliseconds of user silence before Talk mode finalizes and sends the current transcript. Leave unset to keep the platform default pause window (700 ms on macOS and Android, 900 ms on iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Talk Speech Locale`},help:{"v1-1un3x4l-4c":`BCP 47 locale id for Talk speech recognition on device nodes and the iOS system-voice fallback, for example "ru-RU". Leave unset to use each device default.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetry`},help:{"v1-1o5tru3-55":`Explicit consent for anonymous feature statistics attached to the daily update check. Feature statistics are disabled by default and never include messages, credentials, or identifiers.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Feature Statistics Consent Timestamp`},help:{"v1-1t051az-3t":`ISO timestamp recording when the operator accepted or declined anonymous feature statistics. Prevents the setup wizard from asking again.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonymous Feature Statistics`},help:{"v1-1ptrwuq-4r":`Shares enabled channel and provider names, plugin count, and recent session count with the daily update check. Disabled by default and always disabled when DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Tools`},help:{"v1-1el54kl-5h":`Tool infrastructure and cross-agent defaults. Root siblings own infrastructure and cross-agent defaults; agents.defaults owns agent-loop behavior; agent entries may override either where supported.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Agent-to-Agent Tool Access`},help:{"v1-1ynpa5f-cf":`Policy for cross-agent session tool calls: sends, list, history, search, and status reads (default: enabled). Use allow to restrict agent pairs; enabled=false blocks ordinary cross-agent access. Requester-owned native subagent and ACP child sessions stay reachable under tree or all visibility. For strict separation, set tools.sessions.visibility to agent or self (tree still admits requester-owned native/ACP children), or use separate gateways.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Agent-to-Agent Target Allowlist`},help:{"v1-1jt2ari-76":`Agent ids or * patterns that may take part in cross-agent calls; the requesting and target agent must both match. Cross-agent access is on by default, and omitted or empty allow permits every pair. Set an explicit list to restrict access; blank entries deny.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Enable Agent-to-Agent Tool`},help:{"v1-w950oq-ba":`Enables cross-agent session tool access (default: true); omitted or empty allow permits every agent pair. Set false to block ordinary cross-agent access; requester-owned native subagent and ACP child sessions stay reachable under tree or all visibility. For strict separation, set tools.sessions.visibility to agent or self (tree still admits requester-owned native/ACP children), or use separate gateways.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Tool Allowlist`},help:{"v1-1is3eaq-4v":`Absolute tool allowlist that replaces profile-derived defaults for strict environments. Use this only when you intentionally run a tightly curated subset of tool capabilities.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Tool Allowlist Additions`},help:{"v1-1xw9zp8-57":`Extra tool allowlist entries merged on top of the selected tool profile and default policy. Keep this list small and explicit so audits can quickly identify intentional policy exceptions.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Tool Policy by Provider`},help:{"v1-1ecljob-4y":`Per-provider tool allow/deny overrides keyed by channel/provider ID to tailor capabilities by surface. Use this when one provider needs stricter controls than global tool policy.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Code Mode`},help:{"v1-1rlvm8-6k":'Generic Assistant Code Mode. When omitted globally, defaults to `"auto"`; an authored object without `enabled` remains off. Engaged agent runs expose only `exec` and `wait` to the model and access normal tools through the catalog bridge.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Enable Code Mode`},help:{"v1-1nfivj-aj":'Global Assistant Code Mode activation. A completely absent global setting defaults to `"auto"`; an authored object without `enabled` remains off. `"auto"` engages catalog-preferred models, while `true` engages tool-capable runs. Agent and model activation overrides take precedence. An engaged run fails closed if the runtime is unavailable instead of exposing the full tool list.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Code Mode Executor`},help:{"v1-l8nlk2-6x":`JavaScript executor: "node" (default) uses Node vm for trusted code and is not a security sandbox; "quickjs" uses the bundled QuickJS WASM plugin for hardened guest execution. Tool permissions apply to both. A missing selected executor fails closed.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Code Mode Output Limit`},help:{"v1-1hmij9q-1n":`Maximum serialized bytes returned through code-mode output.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Code Mode Pending Tool Limit`},help:{"v1-3b5tyd-2i":`Maximum concurrent nested tool calls a code-mode VM can start before it must resume later.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Code Mode Max Search Results`},help:{"v1-1gpue5r-28":`Maximum number of hidden catalog search results a code-mode program can request.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Code Mode Snapshot Limit`},help:{"v1-1mmgkqy-1x":`Maximum serialized bytes retained for one suspended QuickJS snapshot.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Code Mode Memory Limit`},help:{"v1-xetora-6n":`QuickJS guest heap limit or best-effort Node worker V8 heap budget in bytes. Node runtime overhead and minimum engine allocations affect the effective budget; external buffers and process RSS are excluded. This is not a security guarantee.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Code Mode Surface`},help:{"v1-dsp2b9-2x":'Model-facing surface. Only "only" is supported: expose code-mode `exec` and `wait` and hide normal tools.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Code Mode Default Search Results`},help:{"v1-1io42lu-2m":"Default number of hidden catalog search results returned by `catalog.search` inside code mode."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Code Mode Snapshot TTL`},help:{"v1-1nxfczz-28":"How long suspended Code Mode runs can be resumed with `wait` before they expire."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Code Mode Timeout`},help:{"v1-8csycm-1p":"Maximum milliseconds for one code-mode `exec` or `wait` call."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Tool Denylist`},help:{"v1-wilr1b-4p":`Global tool denylist that blocks listed tools even when profile or provider rules would allow them. Use deny rules for emergency lockouts and long-term defense-in-depth.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Elevated Tool Access`},help:{"v1-ehcm0r-5a":`Elevated tool access controls for privileged command surfaces that should only be reachable from trusted senders. Keep disabled unless operator workflows explicitly require elevated actions.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Elevated Tool Allow Rules`},help:{"v1-1u9bhih-54":`Sender allow rules for elevated tools, usually keyed by channel/provider identity formats. Use narrow, explicit identities so elevated commands cannot be triggered by unintended users.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Enable Elevated Tool Access`},help:{"v1-1n8oyal-4l":`Enables elevated tool execution path when sender and policy checks pass. Keep disabled in public/shared channels and enable only for trusted owner-operated contexts.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec Tool`},help:{"v1-p5piic-56":`Exec-tool policy grouping for shell execution host, security mode, approval behavior, and runtime bindings. Keep conservative defaults in production and tighten elevated execution paths.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`apply_patch Model Allowlist`},help:{"v1-4q5ovf-1x":`Optional allowlist of model ids (e.g. "gpt-5.4" or "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Enable apply_patch`},help:{"v1-1erkir4-31":`Enable or disable apply_patch for OpenAI and OpenAI Codex models when allowed by tool policy (default: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch Workspace-Only`},help:{"v1-x2z207-3o":`Restrict apply_patch paths to the workspace directory (default: true). Set false to allow writing outside the workspace (dangerous).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Exec Approval Running Notice (ms)`},help:{"v1-1gwwann-4z":`Delay in milliseconds before showing an in-progress notice after an exec approval is granted. Increase to reduce flicker for fast commands, or lower for quicker operator feedback.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Exec Ask`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Exec Command Highlighting`},help:{"v1-kyxd4o-4n":`Show parser-derived command highlights in exec approval prompts (default: false). Enable this to render highlighted command text without changing exec approval policy.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Standing Grant Expiry (Days)`},help:{"v1-5uxe2j-6r":`Default lifetime, in days (1-3650), for standing grants minted by allow-always on automation approvals. Unset keeps grants valid until revoked or the owning automation changes. Terms freeze at mint, so changing this affects only future grants.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Exec Target`},help:{"v1-rno1mf-5q":`Selects execution target strategy for shell commands. Use "auto" for runtime-aware behavior (sandbox when available, otherwise gateway), or pin sandbox/gateway/node explicitly when you need a fixed surface.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Exec Mode`},help:{"v1-1wi6t4l-5q":`Normalized exec policy selector. Use "auto" for classifier-reviewed approval misses, "ask" for human-reviewed misses, "allowlist" for deterministic safe commands only, or "full" for trusted local operation.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Exec Node Binding`},help:{"v1-rfnz54-4s":`Node binding configuration for exec tooling when command execution is delegated through connected nodes. Use explicit node binding only when multi-node routing is required.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Exec Notify On Exit`},help:{"v1-1ounlvx-3q":`When true (default), backgrounded exec sessions on exit and node exec lifecycle events enqueue a system event and request a heartbeat.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Exec Notify On Empty Success`},help:{"v1-1wx4xxd-3d":`When true, successful backgrounded exec exits with empty output still enqueue a completion system event (default: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Exec PATH Prepend`},help:{"v1-s1aimc-1r":`Directories to prepend to PATH for exec runs (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Exec Reviewer`},help:{"v1-12y548k-4x":`Model-backed exec reviewer used by auto mode before human approval fallback. Configure a narrow model override here when you want exec review isolated from the main agent model.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Exec Reviewer Fast Mode`},help:{"v1-q3684k-8u":`Optional Fast mode for Assistant approval reviews: true requests priority processing on supported OpenAI Responses and ChatGPT/OAuth routes; false requests standard processing. Omit to preserve provider defaults. Fast mode may cost more and is subject to provider availability. Does not configure native Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Exec Reviewer Model`},help:{"v1-1lltiy5-3i":`Optional provider/model override for the exec reviewer agent. Omit to reuse the configured primary model for the target agent.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Exec Reviewer Thinking`},help:{"v1-1mxw8dy-6u":`Optional reasoning effort for Assistant model-backed approval reviews: minimal, low, medium, high, xhigh, or max. Omit to preserve provider defaults. Supported levels are normalized for the selected model. Does not configure native Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Exec Reviewer Timeout (ms)`},help:{"v1-1o30chi-3w":`Per-stage exec reviewer timeout in milliseconds for model preparation and completion before falling back to human approval (default: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Exec Safe Bin Profiles`},help:{"v1-4cdcwe-29":`Optional per-binary safe-bin profiles (positional limits + allowed/denied flags).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Exec Safe Bins`},help:{"v1-1of1m2s-21":`Allow stdin-only safe binaries to run without explicit allowlist entries.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Exec Safe Bin Trusted Dirs`},help:{"v1-zljbcn-2v":`Additional explicit directories trusted for safe-bin path checks (PATH entries are never auto-trusted).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Exec Security`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Require Inline-Eval Approval`},help:{"v1-jkmgo7-5z":"Require explicit approval for interpreter inline-eval forms such as `python -c`, `node -e`, `ruby -e`, or `osascript -e`. Prevents silent allowlist reuse and downgrades allow-always to ask-each-time for those forms."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Exec Timeout (Seconds)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Workspace-only FS tools`},help:{"v1-1mhuvka-2s":`Restrict filesystem tools (read/write/edit/apply_patch) to the workspace directory (default: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI Identity and Git Author`},help:{"v1-1fl77im-5s":`Managed local GitHub CLI profile and optional Git author for agent tools. Omit this object to preserve the Gateway runtime user's native account and author; repository remote credentials are never overridden.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git Author Email`},help:{"v1-kol5g6-1i":`Optional process-local Git author and committer email.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git Author Name`},help:{"v1-z5bl1f-1h":`Optional process-local Git author and committer name.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`GitHub Credential Kind`},help:{"v1-qi3qun-3q":`Marks a managed OAuth profile whose rotating refresh credential is owned by the Gateway. Omitted profiles use a personal access token.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub Profile Version`},help:{"v1-4lzl0-27":`Opaque generated profile version used to switch managed credentials atomically.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Enable Link Understanding`},help:{"v1-23t2io-59":`Enable automatic link understanding pre-processing so URLs can be summarized before agent reasoning. Keep enabled for richer context, and disable when strict minimal processing is required.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Link Understanding Max Links`},help:{"v1-ksxmcv-52":`Maximum number of links expanded per turn during link understanding. Use lower values to control latency/cost in chatty threads and higher values when multi-link context is critical.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Link Understanding Models`},help:{"v1-6j3mnw-5a":`Preferred model list for link understanding tasks, evaluated in order as fallbacks when supported. Use lightweight models first for routine summarization and heavier models only when needed.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Link Understanding Scope`},help:{"v1-183cwpa-55":`Controls when link understanding runs relative to conversation context and message type. Keep scope conservative to avoid unnecessary fetches on messages where links are not actionable.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Link Understanding Timeout (sec)`},help:{"v1-61v30o-4p":`Per-link understanding timeout budget in seconds before unresolved links are skipped. Keep this bounded to avoid long stalls when external sites are slow or unreachable.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Tool-loop Detection`},help:{"v1-1e3rls8-5g":`Controls rolling-history tool-loop detection and the post-compaction guard. Omit to keep rolling detection off and post-compaction protection on. Set true to enable both, or false to disable both.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Audio Understanding Attachment Policy`},help:{"v1-1s3t9s5-3o":`Choose which matching audio attachments are processed. Use first-only handling unless multi-attachment transcription is intentional.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Transcript Echo Format`},help:{"v1-glpdzh-3i":`Format the echoed transcript with a {transcript} placeholder. Keep the placeholder intact so delivery includes the transcript.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Echo Transcript to Chat`},help:{"v1-1dedp8c-3r":`Echo the audio transcript to the originating chat before agent processing. Enable this when users need to verify what the system heard.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Enable Audio Understanding`},help:{"v1-1v0x7te-2m":`Enable audio understanding so voice notes or audio clips can be transcribed for agent context.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Audio Understanding Language`},help:{"v1-1ruqt97-3z":`Default language hint for audio transcription providers. Set it when the primary spoken language is known and provider detection is unreliable.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Audio Understanding Max Bytes`},help:{"v1-1mcckc8-43":`Default audio input size limit for configured and auto-detected models. Set this to the largest recording your providers and network should accept.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Audio Understanding Max Chars`},help:{"v1-eo1dp-43":`Default maximum transcript length for configured and auto-detected models. Use a lower value to keep long voice notes from expanding agent context.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Preferred Audio Understanding Model`},help:{"v1-1n5zya1-3c":`Prefer one capability-tagged tools.media.models entry for audio transcription before the remaining compatible fallbacks.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Audio Understanding Prompt`},help:{"v1-1v5jtay-4b":`Default audio transcription prompt when a model entry does not override it. Keep the instruction stable when downstream workflows rely on transcript style.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Audio Understanding Scope`},help:{"v1-1pptfg0-3w":`Restrict audio understanding by channel, chat type, or source key. Keep this narrow where automatic transcription is sensitive or expensive.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Audio Understanding Timeout (sec)`},help:{"v1-n8wc6c-3b":`Default timeout for audio understanding requests. Increase it for long recordings or slower local transcription models.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Media Understanding Concurrency`},help:{"v1-13kr9np-58":`Maximum number of concurrent media understanding operations per turn across image, audio, and video tasks. Lower this in resource-constrained deployments to prevent CPU/network saturation.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Image Understanding Attachment Policy`},help:{"v1-11hofbw-3e":`Choose which matching image attachments are processed. Use first-only handling unless multi-image analysis is intentional.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Enable Image Understanding`},help:{"v1-1b2zw34-50":`Enable image understanding so attached or referenced images can be interpreted into textual context. Disable if you need text-only operation or want to avoid image-processing cost.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Image Understanding Max Bytes`},help:{"v1-jwwpd1-3v":`Default image input size limit for configured and auto-detected models. Set this to match provider payload limits and deployment bandwidth.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Image Understanding Max Chars`},help:{"v1-ebnxhk-3q":`Default maximum image description length. Use a lower value for compact context or a higher value for detailed OCR and scene analysis.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Preferred Image Understanding Model`},help:{"v1-1o2uwo6-3c":`Prefer one capability-tagged tools.media.models entry for image understanding before the remaining compatible fallbacks.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Image Understanding Prompt`},help:{"v1-1jdcu8b-3u":`Default image-understanding prompt when an entry does not override it. Keep this deterministic when consumers rely on stable descriptions.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Image Understanding Scope`},help:{"v1-tievo1-3s":`Restrict image understanding by channel, chat type, or source key. Keep this narrow in busy or untrusted channels to control processing.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Image Understanding Timeout (sec)`},help:{"v1-1wcm84x-31":`Default timeout for image-understanding requests. Increase it for large images or slower local vision models.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Media Understanding Shared Models`},help:{"v1-f34u65-47":`Canonical media-understanding model list. Use image, audio, or video capability tags on every entry so each pipeline selects only compatible fallbacks.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Video Understanding Attachment Policy`},help:{"v1-1qm1qrc-3e":`Choose which matching video attachments are processed. Use first-only handling unless multi-video analysis is intentional.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Enable Video Understanding`},help:{"v1-1ltx5gl-58":`Enable video understanding so clips can be summarized into text for downstream reasoning and responses. Disable when processing video is out of policy or too expensive for your deployment.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Video Understanding Max Bytes`},help:{"v1-2mp77v-3v":`Default video input size limit for configured and auto-detected models. Set this to match provider payload limits and deployment bandwidth.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Video Understanding Max Chars`},help:{"v1-1j0x40b-3j":`Default maximum video description length. Use a lower value for compact context or a higher value for detailed scene summaries.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Preferred Video Understanding Model`},help:{"v1-1cygq5k-3c":`Prefer one capability-tagged tools.media.models entry for video understanding before the remaining compatible fallbacks.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Video Understanding Prompt`},help:{"v1-ul2jx4-3r":`Default video-understanding prompt when an entry does not override it. Keep this deterministic when consumers rely on stable summaries.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Video Understanding Scope`},help:{"v1-7gfrx3-3s":`Restrict video understanding by channel, chat type, or source key. Keep this narrow in busy or untrusted channels to control processing.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Video Understanding Timeout (sec)`},help:{"v1-e8rzsy-33":`Default timeout for video-understanding requests. Increase it for longer clips or slower local analysis models.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Message Action Allowlist`},help:{"v1-1iceqwa-5c":`Global message action allowlist for the message tool. Use only when the whole runtime should expose and accept a reduced action set; prefer per-agent allowlists for public or sandboxed agents.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Enable Message Broadcast`},help:{"v1-1ms74z7-14":`Enable broadcast action (default: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Allow Cross-Context (Across Providers)`},help:{"v1-276qxo-2s":`Allow sends across different providers (default: true). Set false to block cross-provider messaging.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Allow Cross-Context (Same Provider)`},help:{"v1-1sg4x49-1z":`Allow sends to other channels within the same provider (default: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Cross-Context Marker`},help:{"v1-1fg6jrp-1z":`Add a visible origin marker when sending cross-context (default: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Cross-Context Marker Prefix`},help:{"v1-eblsru-1p":`Text prefix for cross-context markers (supports "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Cross-Context Marker Suffix`},help:{"v1-1nk0jub-1p":`Text suffix for cross-context markers (supports "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Tool Profile`},help:{"v1-h6k98q-5k":`Global tool profile name used to select a predefined tool policy baseline before applying allow/deny overrides. Use this for consistent environment posture across agents and keep profile names stable.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Sandbox Tool Policy`},help:{"v1-ea7awo-4k":`Tool policy wrapper for sandboxed agent executions so sandbox runs can have distinct capability boundaries. Use this to enforce stronger safety in sandbox contexts.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Sandbox Tool Allow/Deny Policy`},help:{"v1-ub701o-4t":`Allow/deny tool policy applied when agents run in sandboxed execution environments. Keep policies minimal so sandbox tasks cannot escalate into unnecessary external actions.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Session Tools Visibility`},help:{"v1-1vtq2rh-c5":`Controls which sessions can be targeted by sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" default = any session on the Gateway, including other agents and users; "agent" = any session in the current agent id; "self" = only current; "tree" = current session + spawned subagent sessions). Cross-agent access is on by default and scoped by tools.agentToAgent; use narrower visibility to restrict access.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Subagent Tool Policy`},help:{"v1-1xoug01-4z":`Tool policy wrapper for spawned subagents to restrict or expand tool availability compared to parent defaults. Use this to keep delegated agent capabilities scoped to task intent.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Subagent Tool Allow/Deny Policy`},help:{"v1-7vxsbf-5d":`Allow/deny tool policy applied to spawned subagent runtimes. Keep this narrower than parent scope. Parent-owned tools such as progress_card are always denied, including through allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Swarm`},help:{"v1-1q96vvs-45":`Collector-mode subagent orchestration. Enabled by default; set false to opt out. Tool permissions still apply to agents_wait and swarm spawn options.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Swarm Default Agent`},help:{"v1-p4alpg-2m":`Default target agent for swarm spawns that omit agentId. The subagent allowlist still applies.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Enable Swarm`},help:{"v1-1nnnrq9-2e":`Enables collector-mode subagents and agents_wait. Default is on; set false to opt out.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Swarm Live Children per Group`},help:{"v1-kfx6qp-1c":`Maximum live collector children per swarm group.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Swarm Concurrent Children`},help:{"v1-1d46jtm-1s":`Maximum concurrently running collector children per swarm group.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Swarm Total Children per Group`},help:{"v1-1gc9vl1-1e":`Maximum lifetime collector spawns per swarm group.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Swarm Maximum Wait Timeout`},help:{"v1-bog18y-1g":`Maximum timeout accepted by agents_wait, in seconds.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Tool Search`},help:{"v1-17m5go0-7y":`Compact large Assistant, MCP, and client tool catalogs. Runtimes use structured Tool Search automatically when unset; engaged Code Mode takes precedence and Codex uses its native search. Set false to disable it, true for the code bridge, or use the object form to choose a mode.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Tool Search Code Timeout`},help:{"v1-105r499-34":"Maximum milliseconds for one `tool_search_code` execution. Runtime clamps values to the supported 1s..60s range."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Enable Tool Search`},help:{"v1-1wwbid7-4h":"Enables Tool Search. When on, Assistant hides large tool catalogs behind `tool_search_code` or structured search/describe/call tools during embedded runtime runs."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Tool Search Max Results`},help:{"v1-7du4kh-32":`Maximum number of Tool Search results a model can request. Runtime clamps values to the supported 1..50 range.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Tool Search Surface`},help:{"v1-jybcbe-7x":'Choose the model-facing surface: "code" exposes `tool_search_code`; "tools" exposes structured search/describe/call fallback tools; "directory" keeps a bounded tool directory visible, exposes a bounded set of likely or required schemas, and defers the rest behind search/describe/call.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Tool Search Default Results`},help:{"v1-1uchq7t-39":"Default number of Tool Search results returned when the model omits a limit. Runtime clamps this to `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Enable Structured Plan Tool`},help:{"v1-1xgegme-4o":"Unified `progress_card` status tool for durable plans and narrative notes in parent sessions. Enabled by default; set false to opt out. Always unavailable to subagents."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Web Tools`},help:{"v1-fpsy5-4y":`Web-tool policy grouping for search/fetch providers, limits, and fallback behavior tuning. Keep enabled settings aligned with API key availability and outbound networking policy.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Web Fetch Cache TTL (min)`},help:{"v1-1hk89qp-17":`Cache TTL in minutes for web_fetch results.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Enable Web Fetch Tool`},help:{"v1-yrswld-1f":`Enable the web_fetch tool (lightweight HTTP fetch).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Web Fetch Request Headers`},help:{"v1-16bjkv5-me":"Extra request headers sent with direct web_fetch requests, for example gateway routing or authentication headers. Every configured value is treated as sensitive and redacted from exposed config and debug captures. Values are plain strings, support ${VAR} substitution and the global $${VAR} literal escape, and are sent to model-chosen URLs. Entries are validated when the request is built rather than at config load, so a bad name or unsendable value is dropped and logged instead of disabling the surface; Accept, Accept-Language, User-Agent, and framing headers such as Transfer-Encoding are dropped too. Use tools.web.fetch.userAgent to change the user agent. Cross-origin redirects retain only the guarded-fetch safe header allowlist, and changing the headers actually sent partitions the fetch cache."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Web Fetch Max Chars`},help:{"v1-12d1fw7-1d":`Max characters returned by web_fetch (truncated).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Web Fetch Hard Max Chars`},help:{"v1-cl2mf1-1v":`Hard cap for web_fetch maxChars (applies to config and tool calls).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Web Fetch Max Redirects`},help:{"v1-t6eak9-1h":`Maximum redirects allowed for web_fetch (default: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Web Fetch Max Download Size (bytes)`},help:{"v1-q6ld9c-10":`Max download size before truncation.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Web Fetch Provider`},help:{"v1-6pb3nv-v":`Web fetch fallback provider id.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Web Fetch Readability Extraction`},help:{"v1-19exqzx-2c":`Use Readability to extract main content from HTML (fallbacks to basic HTML cleanup).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Web Fetch SSRF Policy`},help:{"v1-qtn7zx-3c":`Scoped SSRF policy overrides for web_fetch. Keep this narrow and opt in only for known local-network proxy environments.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Web Fetch Allowed Hostnames`},help:{"v1-1j9ctya-35":`Exact hostnames or IP literals allowed for web_fetch, including otherwise blocked targets. Keep the list minimal.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Web Fetch Allow IPv6 Unique Local Range`},help:{"v1-1eyz55i-3b":`Allow IPv6 Unique Local Addresses (fc00::/7) for trusted fake-IP proxy compatibility such as sing-box, Clash, or Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Web Fetch Allow RFC 2544 Benchmark Range`},help:{"v1-u5asdb-2y":`Allow RFC 2544 benchmark-range IPs (198.18.0.0/15) for fake-IP proxy compatibility such as Clash or Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Web Fetch Blocked Hostnames`},help:{"v1-1164vvk-66":`Hostname patterns denied before DNS and allow rules on every web_fetch redirect. Supports exact hosts and "*.example.com" for subdomains only; add "example.com" separately to block the apex. Empty or unset adds no denials.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Web Fetch Dangerously Allow Private Network`},help:{"v1-2s6mv7-3t":`Allows web_fetch access to private and internal network targets. Keep disabled unless model-selected URLs are trusted in this deployment.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Web Fetch Timeout (sec)`},help:{"v1-1c3yfr4-16":`Timeout in seconds for web_fetch requests.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`Web Fetch User-Agent`},help:{"v1-s7pe8j-1e":`Override User-Agent header for web_fetch requests.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Web Fetch Trusted Env Proxy`},help:{"v1-1ypkqj7-54":`Route web_fetch through a trusted HTTP(S) env proxy and let the proxy resolve DNS. Enable only when that proxy is operator-controlled and enforces outbound policy after DNS resolution.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`Web Search Cache TTL (min)`},help:{"v1-6trzlf-18":`Cache TTL in minutes for web_search results.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Enable Web Search Tool`},help:{"v1-n1cm4y-27":`Enable managed web_search and optional Codex-native search for eligible models.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Web Search Max Results`},help:{"v1-mrw7mi-z":`Number of results to return (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Codex Allowed Domains`},help:{"v1-1cv4y44-43":`Domain allowlist for native Codex web_search. On native-hosted-search turns, it also gates managed web_fetch; managed-provider turns are unchanged.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Codex Search Context Size`},help:{"v1-antack-1u":`Native Codex search context size hint: "low", "medium", or "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Enable Native Codex Web Search`},help:{"v1-ek2jzd-1k":`Enable native Codex web search for Codex-capable models.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Codex Web Search Mode`},help:{"v1-1ahyq9f-32":`Native Codex web search preference: "cached" (default; unrestricted Codex turns resolve it to live) or "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Codex User City`},help:{"v1-1y95orp-1d":`Approximate city sent to native Codex web search.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Codex User Country`},help:{"v1-1xkm5ms-1g":`Approximate country sent to native Codex web search.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Codex User Region`},help:{"v1-lhar02-1l":`Approximate region/state sent to native Codex web search.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Codex User Timezone`},help:{"v1-fgv9fh-1h":`Approximate timezone sent to native Codex web search.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Web Search Provider`},help:{"v1-10omglr-1x":`Search provider id. Auto-detected from available API keys if omitted.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Web Search Timeout (sec)`},help:{"v1-i0egvw-17":`Timeout in seconds for web_search requests.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transcripts`},help:{"v1-1i0sc09-66":`Core transcript capture settings for meeting notes, recording-capable agent tools, and configured live meeting auto-start sources. Meeting plugins capture durable notes by default; set enabled to false to opt out globally.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Transcripts Auto-start Sources`},help:{"v1-1mzsl79-5s":`Live transcript sources managed automatically from gateway startup. Each entry is enabled by being present; remove an entry to disable that source. Sources capture continuously unless whenOccupied is enabled.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Transcript Account ID`},help:{"v1-6g2kjj-4b":`Optional provider account or workspace identifier for transcript sources that need account disambiguation. Use the provider's documented account id format.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Transcript Channel ID`},help:{"v1-1lk9d5o-4u":`Provider channel id for the live transcript source, such as a Discord voice channel or Slack huddle channel. Verify provider-specific id semantics before enabling auto-start.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord Guild ID`},help:{"v1-fyfgnk-4l":`Optional Discord guild id for Discord voice transcript sources. Configure this with the matching channelId when the provider needs guild-scoped voice channel lookup.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Transcript Meeting URL`},help:{"v1-1xtt9ci-4f":`Optional meeting URL for providers that join by URL instead of channel id. Use only trusted meeting links because auto-start may join and capture that meeting.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Transcript Source Provider ID`},help:{"v1-1uur06p-3s":`Transcript source provider id, such as a Discord voice or future Slack huddle provider. Use the exact id exposed by the provider plugin.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Transcript Session ID`},help:{"v1-xyo4x5-5o":`Optional fixed transcript session id for this auto-start source. Ignored when whenOccupied is true. Leave unset for generated ids unless you need a stable daily selector and can avoid same-day collisions.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Transcript Title`},help:{"v1-ycjnmp-5y":`Optional title for future transcript captures. Changing only titles keeps current captures running and does not rename their admitted title or saved notes. Other source changes retain their normal restart handling.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Transcript Capture When Occupied`},help:{"v1-34jid4-78":`Start a fresh transcript session each time humans are present in the source and stop it (generating notes) after the last human leaves. Requires a provider that reports occupancy, such as discord-voice. Default: false (capture continuously from gateway start).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transcripts Enabled`},help:{"v1-fyqqr0-6d":`Enables durable automatic meeting notes, the transcripts agent tool, and configured auto-start sources. Default: true. Set false to disable persistence and the tool; explicit meeting transcribe mode retains its bounded live tail.`}},tts:{label:{"v1-bmxkk9-e":`Text-to-Speech`},help:{"v1-1o27tk2-4n":`Text-to-speech policy for reading agent replies aloud on supported voice or audio surfaces. Keep disabled unless voice playback is part of your operator/user workflow.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS Persona`},help:{"v1-1r0opcb-29":`Default TTS persona id. Local TTS persona preferences can override this per host.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS Personas`},help:{"v1-19aybhl-2l":`Named TTS personas that define stable spoken identity plus provider-specific speech bindings.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS Persona`},help:{"v1-10s52ah-2l":`One TTS persona. Use provider-specific bindings for exact voices/models and prompt templates.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`TTS Persona Provider Bindings`},help:{"v1-993jop-3e":`Provider-specific TTS persona bindings keyed by speech provider id. These merge over tts.providers for the active persona.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`TTS Provider Settings`},help:{"v1-1k80nl4-4y":`Provider-specific TTS settings keyed by speech provider id. Use this instead of bundled provider-specific top-level keys so speech plugins stay decoupled from core config schema.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`TTS Provider Config`},help:{"v1-dwapva-3d":`Provider-specific TTS configuration for one speech provider id. Keep fields scoped to the plugin that owns that provider.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`TTS Provider API Key`},help:{"v1-1m2fj0i-2o":`Provider API key used by that speech provider when its plugin requires authenticated TTS access.`}},tui:{label:{"v1-c8hus1-b":`Terminal UI`},help:{"v1-1fg9vw2-3s":`Terminal UI display settings. Use this section for terminal-only presentation preferences without changing Gateway or other UI behavior.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Terminal UI Footer`},help:{"v1-6e12l3-3k":`Terminal UI footer display settings. Keep optional context compact so session, model, goal, and token information stay readable.`}},ui:{label:{"v1-ye4dff-2":`UI`},help:{"v1-dt1924-42":`UI presentation settings for accenting and operator display preferences. Use this for readability customization without changing runtime behavior.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`User Accent Color`},help:{"v1-16klzws-4z":`Control UI accent: #RRGGBB for a custom color, or 'theme' for the selected theme’s palette. Overrides ui.seamColor; clear it to inherit the configured seam color or theme default.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Accent Color`},help:{"v1-14q3r4h-4g":`Primary accent color used by UI surfaces for emphasis, badges, and visual identity cues. Use high-contrast values that remain readable across light/dark themes.`}},update:{label:{"v1-k12u1x-7":`Updates`},help:{"v1-5p8qnv-5c":`Update-channel and startup-check behavior for keeping Runtime versions current. Use conservative channels in production and more experimental channels only in controlled environments.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Auto Update Enabled`},help:{"v1-49xs2h-3c":`Enable background auto-update for stable and beta package installs; extended-stable never auto-applies (default: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Update Channel`},help:{"v1-lqtdvf-5b":`Update channel for git + npm installs ("stable", "extended-stable", "beta", or "dev"). Extended-stable is package-only: installation is foreground-only, with optional read-only startup hints.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Update Check on Start`},help:{"v1-qy3q9g-5v":`Checks for updates when the Gateway starts, including read-only extended-stable hints (default: true). Set false to disable automatic Gateway and headless-node update checks, applies, and anonymous update pings.`}},voicewake:{label:{"v1-txt1wb-a":`Voice Wake`}},web:{label:{"v1-1ae9z56-b":`Web Channel`}},wizard:{label:{"v1-28jonk-h":`Setup Preferences`},help:{"v1-14jh6rm-3b":`User-owned setup preferences. Machine-owned wizard history and acknowledgement state live in the shared state database.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Setup Discovery Access`},help:{"v1-1nqxt0w-38":`Discovery consent for guided setup: "full" scans silently while "guarded" asks before inspecting local applications.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Setup App Recommendations`},help:{"v1-ub8uoi-30":`Controls whether guided setup may use installed-application labels to recommend relevant plugins and skills.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Wizard Last Run Timestamp`},help:{"v1-1y0fbk-1k":`Timestamp of the last successfully committed wizard run.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Wizard Last Run Command`},help:{"v1-x2pfkk-15":`Command that invoked the last wizard run.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Wizard Last Run Commit`},help:{"v1-h0jkmt-1i":`Source commit used by the last development wizard run.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Wizard Last Run Mode`},help:{"v1-16508qy-1r":`Whether the last wizard run targeted "local" or "remote" setup.`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Wizard Last Run Version`},help:{"v1-1nj7xf9-19":`Assistant version used by the last wizard run.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Wizard Security Acknowledgement Timestamp`},help:{"v1-86i182-2a":`Timestamp of the setup security acknowledgement, committed with the target config.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Worktree Acceleration`},help:{"v1-9es3gc-4r":`Use filesystem acceleration for new managed worktrees when supported (default: true). Set false to use normal Git checkout and file copying. Applies only to new worktrees.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Worktree Root`},help:{"v1-1tgti9j-5d":`Global directory for new managed worktrees. Use an absolute path or ~ for your home directory; defaults to <state-dir>/worktrees. Existing worktrees keep their recorded paths when this changes.`}}}}})))()}export{t as n,n as t};